const a={1:[["1","Saygıdeğer Teofilos, Birçokları aramızda gerçekleşmiş olan olayların tarihçesini düzene koymaya giriştiklerinden,"],["2","başlangıçtan beri görgü tanıkları ve sözün hizmetkârları olanlar bunları bize ilettikleri gibi,"],["3","ben de baştan beri her şeyin seyrini titizlikle araştırdıktan sonra, sana sırasıyla yazmayı uygun gördüm."],["4","Öyle ki, sana iletilen bu şeylerin kesinliğinden emin olabilesin."],["5","Yahudiye Kralı Hirodes günlerinde, Aviya bölüğünden Zekariya adında bir kâhin vardı. Aron kızlarından gelen karısının adı Elizabet’ti."],["6","Her ikisi de Tanrı önünde doğru kişilerdi, Efendi’nin bütün buyrukları ve kurallarında kusursuzca yürümekteydiler."],["7","Ancak çocukları yoktu. Çünkü Elizabet kısırdı ve ikisinin de yaşı oldukça ilerlemişti."],["8","Zekariya kendi bölüğünün sırasında Tanrı önünde kâhinlik görevini yerine getirirken,"],["9","kâhinlik geleneği uyarınca Efendi’nin Tapınağı’na girip buhur yakma kurası ona düştü."],["10","Buhur saatinde bütün halk kalabalığı dışarıda dua ediyordu."],["11","Efendi’nin bir meleği buhur sunağının sağ tarafında durup ona göründü."],["12","Zekariya onu görünce şaştı ve üzerine korku çöktü."],["13","Ama melek ona, “Korkma Zekariya, çünkü dileğin işitildi. Karın Elizabet sana bir oğul doğuracak ve adını Yuhanna koyacaksın."],["14","Sana sevinç ve coşku verecek ve birçokları onun doğumuna sevinecek."],["15","Çünkü o Efendi’nin önünde büyük biri olacak. ‘Hiç şarap ve içki içmeyecek’, daha annesinin karnındayken Kutsal Ruh’la dolacak."],["16","İsrael'in çocuklarından birçoğunu Tanrıları Efendi’ye döndürecek."],["17","Babaların yüreklerini çocuklara, söz dinlemeyenleri doğruların bilgeliğine döndürmek, Efendi’ye hazırlanmış bir halk hazırlamak için Eliya’nın ruhu ve gücüyle Efendi’nin önünden gidecek” dedi."],["18","Zekariya meleğe, “Bundan nasıl emin olabilirim? Çünkü ben yaşlı bir adamım ve karımın yaşı da oldukça ilerledi” dedi."],["19","Melek ona, “Ben Tanrı’nın önünde duran Gabriel’im. Seninle konuşmak ve bu müjdeyi sana bildirmek için gönderildim."],["20","İşte, dilin tutulacak ve bu şeyler olana dek konuşamayacaksın, Çünkü uygun zamanda yerine gelecek olan bu sözlerime inanmadın.”"],["21","Halk Zekariya’yı bekliyordu. Tapınakta gecikmesine şaşmışlardı."],["22","Dışarı çıktığında onlarla konuşamadı. Onlar da tapınakta bir görüm gördüğünü anladılar. Onlara işaretler yapıyordu ama dili tutuk kalmıştı."],["23","Görev günleri dolunca Zekariya evine geri döndü."],["24","O günlerden sonra karısı Elizabet gebe kaldı ve beş ay evine kapandı."],["25","“Efendi halimi gördü, insanlar arasındaki utancımı kaldırmak için bana böyle yaptı” dedi."],["26","Tanrı, altıncı ayda, Melek Gabriel’i, Galile’de bulunan Nazaret Kenti’ne,"],["27","David'in evinden Yosef adlı bir adamla nişanlı olan el değmemiş bir kıza gönderdi. Bakirenin adı Mariyam’dı."],["28","Melek içeri girdikten sonra ona, “Sevin, ey çok lütfedilmiş olan! Efendi seninledir. Kadınlar arasında ne mutlu sana!” dedi."],["29","Ne var ki Mariyam onu görünce, bu sözlere çok şaşırdı, bu nasıl bir selam diye düşündü."],["30","Melek ona, “Korkma Mariyam, çünkü Tanrı’da lütuf buldun” dedi."],["31","İşte, gebe kalıp bir oğul doğuracak ve adını ‘Yeşua’ koyacaksın."],["32","O büyük olacak ve kendisine En Yüce Olan’ın Oğlu denecek. Efendi Tanrı O’na atası David’in tahtını verecek."],["33","O, Yakov’un evi üzerinde sonsuza dek hüküm sürecek, O'nun krallığının sonu olmayacak.”"],["34","Mariyam meleğe, “Ben bakire olduğum halde, bu nasıl olabilir?” dedi."],["35","Melek ona şöyle yanıt verdi: “Kutsal Ruh üzerine gelecek ve Yüce Olan'ın gücü üzerine gölge salacak. Bu nedenle, senden doğacak olan kutsal Olan'a, Tanrı’nın Oğlu denecek."],["36","İşte, akraban Elizabet de yaşlılığında bir oğula gebe kaldı. Kısır denilen bu kadın altıncı ayındadır."],["37","Çünkü Tanrı'nın söylediği hiçbir şey imkânsız değildir.”"],["38","Mariyam, “İşte, Efendi’nin hizmetkârı. Bana dediğin gibi olsun” dedi. Bunun üzerine melek onun yanından ayrıldı."],["39","Mariyam o günlerde Yahuda’nın dağlık bölgesindeki bir kente gitmek üzere aceleyle gitti."],["40","Zekariya’nın evine girip Elizabet’i selamladı."],["41","Elizabet Mariyam’ın selamını duyar duymaz, karnındaki bebek sıçradı. Elizabet Kutsal Ruh’la doldu."],["42","Yüksek sesle seslenip dedi, “Sen kadınlar arasında kutsanmış olansın, rahminin ürünü de kutsanmıştır!"],["43","Efendim’in annesinin yanıma gelme lütfu bana neden böyle bağışlandı?"],["44","İşte, senin selamının sesi kulağıma ulaştığında, karnımdaki çocuk sevinçle sıçradı!"],["45","Efendi’nin kendisine söylemiş olduğu sözlerin gerçekleşeceğine iman eden kadına ne mutlu!”"],["46","Mariyam şöyle dedi: “Canım Efendi’yi yüceltir."],["47","Ruhum, Kurtarıcım Tanrı’da sevinç bulur,"],["48","çünkü O, hizmetkârının sıradan olan durumunu gördü. Çünkü işte, bundan böyle bütün kuşaklar bana kutsanmış diyecekler."],["49","Çünkü Güçlü Olan, benim için büyük işler yaptı. O’nun adı kutsaldır."],["50","O’nun merhameti, kuşaklar boyunca kendisinden korkanların üzerindedir."],["51","Koluyla kuvvetini gösterdi. Gururluları yüreklerinin kuruntusunda dağıttı."],["52","Hükümdarları tahtlarından indirdi, sıradan insanları yükseltti."],["53","Açları iyi şeylerle doyurdu. Zenginleri boş gönderdi."],["54","Atalarımıza, Avraham’a ve soyuna sonsuza dek söz verdiği gibi,"],["55","merhamet etmeyi hatırlayarak hizmetkârı İsrael’e yardım etti.”"],["56","Mariyam yaklaşık üç ay kadar Elizabet’in yanında kaldı, sonra evine döndü."],["57","Elizabet’in doğurma vakti gelince, bir oğul doğurdu."],["58","Komşuları ve akrabaları, Efendi’nin ona büyük merhamet ettiğini duydular ve onunla birlikte sevindiler."],["59","Sekizinci gün çocuğu sünnet etmeye geldiler. Ona babası Zekariya’nın adını vermek istediler."],["60","Annesi, “Hayır, adı Yuhanna olacak” dedi."],["61","Ona, “Akrabalarından bu adla kimse yok” dediler."],["62","Bunun üzerine, çocuğa hangi adı koymak istediğini babasına işaretle sordular."],["63","Zekariya bir yazı levhası istedi ve “Adı Yuhanna’dır” diye yazdı. Herkes şaştı."],["64","Hemen Zekariya’nın ağzı açıldı, dili çözüldü. Tanrı’yı yücelten sözler söyledi."],["65","Çevrede bulunanların hepsinin üzerine korku geldi. Bütün bu sözler Yahudiye’nin dağlık bölgesinin her yerinde konuşuldu."],["66","Bunları duyanların hepsi, “Acaba bu çocuk ne olacak?” diye yüreklerinde biriktirdiler. Çünkü Efendi'nin eli onunla birlikteydi."],["67","Babası Zekariya Kutsal Ruh’la doldu ve peygamberlik edip şöyle dedi:"],["68","“İsrael’in Tanrısı Efendi’ye övgüler olsun, çünkü halkını ziyaret ederek fidyeyle kurtarmaya geldi."],["69","Hizmetkârı David’in soyundan bizim için kurtuluş boynuzu çıkardı."],["70","Eski zamanlardan beri kutsal peygamberlerin ağzından söylediği gibi,"],["71","bizden nefret eden herkesin elinden kurtuluşumuzu sağladı."],["72","Atalarımıza merhamet ederek kutsal antlaşmasını anmış oldu."],["73","Atamız Avraham'a ant içerek,"],["74","düşmanlarımızın elinden kurtaracağına, ömrümüzün bütün günlerinde,"],["75","O’nun önünde kutsallık ve doğruluk içinde, korkmadan O’na hizmet edeceğimize söz vermişti."],["76","Ve sen, ey çocuk, En Yüce Olan’ın peygamberi olarak anılacaksın. Çünkü Efendi’nin önünden O’nun yollarını hazırlamak için gideceksin,"],["77","ve O’nun halkına, günahlarının bağışlanmasıyla kurtulacaklarının bilgisini vereceksin."],["78","Tanrımız’ın şefkatli merhameti sayesinde, yücelerden doğan güneş bizi ziyaret edecek."],["79","Karanlıkta ve ölümün gölgesinde oturanların üzerine parlayacak, ayaklarımızı esenlik yoluna yöneltecek.”"],["80","Çocuk büyüyor, ruhta güçleniyordu. İsrael’de görüneceği güne dek ıssız yerlerde kaldı."]],2:[["1","O günlerde, Sezar Augustus'tan bütün dünyanın kaydı yapılsın diye bir buyruk çıktı."],["2","Bu ilk kayıt, Kirinius’un Suriye valisi olduğu zaman yapıldı."],["3","Herkes kayıt olmak için kendi kentine gitti."],["4","Yosef de David’in aile evinden olduğu için Galile’nin Nazaret kentinden Yahudiye’ye, David’in kenti Beytlehem’e gitti."],["5","Orada, gebe olan nişanlısı Mariyam’la birlikte kayıt olacaktı."],["6","Onlar oradayken, Mariyam’ın doğurma günü geldi."],["7","İlk oğlunu doğurdu. O’nu kundağa sarıp bir yemliğe yatırdı. Çünkü onlar için handa yer yoktu."],["8","Aynı yörede, sürülerinin başında nöbet tutarak geceleyin kırda kalan çobanlar vardı."],["9","İşte, Efendi’nin bir meleği onların yanında durdu ve Efendi’nin görkemi çevrelerini aydınlattı. Dehşete kapıldılar."],["10","Melek onlara, “Korkmayın, çünkü işte, size tüm insanlığı çok sevindirecek bir haber müjdeliyorum” dedi."],["11","“Bugün size, David’in kentinde bir Kurtarıcı doğdu. Bu, Efendi olan Mesih’tir."],["12","İşte size işaret: Kundağa sarılmış ve yemlikte yatan bir bebek bulacaksınız.”"],["13","Ansızın melekle birlikte kalabalık bir göksel ordu Tanrı’yı överek şöyle dediler:"],["14","“En yücelerde Tanrı’ya yücelik olsun, yeryüzünde esenlik, insanlara iyilik olsun.”"],["15","Melekler yanlarından ayrılıp göğe çekilince, çobanlar birbirlerine, “Haydi, şimdi Beytlehem’e gidelim ve Efendi’nin bize bildirdiği olup biten bu şeyi görelim” dediler."],["16","Koşarak geldiler. Mariyam’ı Yosef’i ve yemlikte yatan bebeği buldular."],["17","Bunu gördüklerinde, çocuk hakkında kendilerine anlatılanları etrafa yaydılar."],["18","Bunu duyanların hepsi çobanların kendilerine söylediklerine şaştılar."],["19","Ama Mariyam bütün bu sözleri yüreğinde saklıyor, üzerinde derin derin düşünüyordu."],["20","Çobanlar, kendilerine söylendiği gibi, duydukları ve gördükleri her şey için Tanrı’yı yüceltip överek geri döndüler."],["21","Sekizinci gün, çocuğun sünnet zamanı dolunca, anne rahmine düşmeden meleğin söylemiş olduğu gibi, O’na Yeşua adı verildi."],["22","Moşe’nin Yasası’na göre arınma günleri dolunca, Yosef’le Mariyam çocuğu Efendi’ye sunmak için Yeruşalem’e,"],["23","Yasa’da yazıldığı gibi, “Rahmi açan her erkek çocuk Efendi’ye kutsal sayılacak,”"],["24","ve Yasa’da da denildiği gibi, kurban olarak “bir çift kumru ya da iki güvercin” sunmaya götürdüler."],["25","İşte o sırada, Yeruşalem’de Şimon adında bir adam vardı. Şimon doğru ve inançlı biriydi. İsrael’in teselli bulmasını bekliyordu. Kutsal Ruh onun üzerindeydi."],["26","Efendi’nin Mesih’ini görmeden ölmeyeceği Kutsal Ruh tarafından kendisine açıklanmıştı."],["27","Şimon Ruh’da tapınağın içine geldi. Ailesi Yasa’ya göre adet olanı O'nun için yapmak üzere küçük Yeşua’yı içeri getirdiklerinde,"],["28","Şimon O’nu kucağına aldı. Tanrı’yı yücelterek şunları söyledi:"],["29","“Ey Efendim, sözüne göre, artık esenlik içinde hizmetkarını bırakıyorsun,"],["30","çünkü gözlerim kurtarışını gördü,"],["31","bütün halkların önünde hazırladığın;"],["32","ulusları aydınlatıp, halkın İsrael’in yüceliği olan ışığı gördüm.”"],["33","Yosef’le annesi O’nun hakkında söylenen şeylere şaştılar."],["34","Şimon onları kutsadı ve annesi Mariyam’a şöyle dedi: “İşte, bu çocuk İsrael’de birçoklarının düşmesi ve kalkması için atanmıştır. Hem de karşı konuşulacak bir belirtidir."],["35","Birçoklarının yüreğindeki düşünceleri açığa çıkarırken, senin kendi canını da bir kılıç delecek.”"],["36","Aşer oymağından Fanuel’in kızı Anna adında çok yaşlı bir peygamber vardı. Kızlığından sonra kocasıyla yedi yıl yaşamıştı."],["37","Seksen dört yıldır duldu. Tapınaktan ayrılmaz, gece gündüz oruçla, duayla tapınırdı."],["38","Tam o saatte çıkan Anna, Tanrı’ya şükrederek Yeruşalem’in kurtuluşunu bekleyen herkese Yeşua’dan söz etmeye başladı."],["39","Efendi’nin Yasası uyarınca gereken her şeyi tamamladıktan sonra Yosef’le Mariyam Galile’ye, kendi kentleri Nazaret’e döndüler."],["40","Çocuk büyüyor, ruhta güçleniyor, bilgelikle doluyordu. Tanrı’nın lütfu O’nun üzerindeydi."],["41","Anne babası her yıl Pesah Bayramı’nda Yeruşalem’e giderdi."],["42","Yeşua on iki yaşındayken, bayram geleneği uyarınca Yeruşalem’e çıktılar."],["43","Bayram günlerini doldurup eve dönerlerken küçük Yeşua Yeruşalem’de geride kaldı. Mariyam’la Yosef bunu bilmiyordu."],["44","O’nun yol arkadaşlarıyla birlikte olduğunu düşünerek bir günlük yol mesafesi gittiler. Sonra O’nu akrabalar ve tanıdıklar arasında aradılar."],["45","O’nu bulamayınca, O’nu arayarak Yeruşalem’e döndüler."],["46","Üç gün sonra O’nu tapınakta, öğretmenler arasında otururken buldular. Onları dinliyor, sorular soruyordu."],["47","O’nu dinleyenlerin hepsi anlayışına ve verdiği yanıtlara hayran kalıyorlardı."],["48","Mariyam ve Yosef O’nu görünce şaşırdılar. O’na, “Oğlum, bize neden böyle davrandın? İşte, babanla ben kaygı içinde seni arıyorduk” dedi."],["49","Onlara, “Beni neden arıyorsunuz? Babamın evinde olmam gerektiğini bilmiyor muydunuz?” dedi."],["50","Onlar kendilerine söylemiş olduğu O'nun bu sözünü anlamadılar."],["51","Yeşua onlarla birlikte yola koyulup Nazaret’e geldi. Onlara itaat ederdi. Annesi bütün bu sözleri yüreğinde sakladı."],["52","Yeşua, bilgelikte ve boyda büyüyordu, Tanrı’nın ve insanların beğenisininde de öyle."]],3:[["1","Sezar Tiberius’un hükmünün on beşinci yılında, Pontius Pilatus Yahudiye valisiydi. Galile’yi Hirodes, İtureya ve Trahonitis bölgesini, Hirodes’in kardeşi Filipus, Avilini’yi Lisanias yönetiyordu."],["2","Hanan ile Kayafa’nın başkâhinliği döneminde, Zekariya oğlu Yuhanna’ya çölde Tanrı sözü geldi."],["3","Yuhanna Yarden çevresindeki bütün bölgeye, günahların bağışlanması için tövbe vaftizini duyurarak geldi."],["4","Peygamber Yeşaya’nın sözleri kitabında yazıldığı gibi, “Çölde çağıranın sesi, ‘Efendi’nin yolunu hazırlayın. O'nun yollarını düzleyin’ diyor."],["5","‘Her vadi doldurulacak. Her dağ ve tepe alçaltılacaktır. Eğri olan doğrultulacak, sarp yollar düzleştirilecek."],["6","Bütün insanlık Tanrı’nın kurtarışını görecektir.’”"],["7","Yuhanna, kendisi tarafından vaftiz edilmek üzere çıkıp gelen kalabalıklara şöyle dedi: “Ey engerekler soyu! Gelecek gazaptan kaçmanız için sizi kim uyardı?"],["8","Bu nedenle artık tövbeye layık meyveler verin! Kendi aranızda, ‘Biz Avraham’ın soyundanız’ demeye başlamayın. Size şunu söyleyeyim: Tanrı Avraham’a şu taşlardan çocuk yetiştirebilir!"],["9","Şimdiden balta ağaçların köküne dayanmıştır. Bu nedenle iyi meyve vermeyen her ağaç kesilir ve ateşe atılır.”"],["10","Kalabalık O’na, “Öyleyse ne yapmalıyız?” diye sordu."],["11","Onlara şu karşılığı verdi: “İki ceketi olan, olmayana versin. Kimin yiyeceği varsa, o da öyle yapsın.”"],["12","Vergi görevlileri de vaftiz olmaya geldiler ve ona, “Öğretmenimiz, biz ne yapmalıyız?” dediler."],["13","Onlara, “Size belirlenmiş olandan fazlasını toplamayın” dedi."],["14","Askerler de, “Ya biz, biz ne yapalım?” diye sordular. Onlara, “Kimseyi sıkıştırıp soymayın, yalan yere kimseyi suçlamayın. Aldığınız maaşla yetinin” dedi."],["15","Halk umut içinde bekliyordu. Yuhanna hakkında, “Acaba Mesih o mu?” diye herkes yüreğinde düşünüyordu."],["16","Yuhanna onların hepsine şu yanıtı verdi: “Ben sizi suyla vaftiz ediyorum, ama benden daha güçlü Olan geliyor. Ben O’nun çarıklarının bağını çözmeye layık değilim. O sizi Kutsal Ruh’la ve ateşle vaftiz edecek."],["17","Yabası elindedir, harman yerini tamamen temizleyecek ve buğdayı ambarına toplayacak. Samanı ise sönmez ateşte yakacaktır.”"],["18","Yuhanna daha birçok konuda uyarıyor, Müjde’yi halka duyuruyordu."],["19","Ne var ki Tetrark Hirodes, kardeşinin karısı Hirodiya ile ilgili olarak ve kendi yapmış olduğu bütün kötülükler nedeniyle Yuhanna tarafından kınanıyordu."],["20","Hirodes kötülüklerine bir yenisini ekleyerek Yuhanna’yı zindana attırdı."],["21","Bütün halk vaftiz olduktan sonra, Yeşua da vaftiz oldu. Dua ederken gök açıldı."],["22","Kutsal Ruh, fiziksel görünümde, güvercin gibi Yeşua’nın üzerine indi. Gökten, “Sen benim sevgili Oğlum’sun. Senden hoşnudum” diyen bir ses geldi."],["23","Yeşua öğretmeye başladığında otuz yaşlarındaydı. Yosef’in oğlu sanılıyordu. Yosef de Eli oğlu,"],["24","Mattat oğlu, Levi oğlu, Malki oğlu, Yannay oğlu, Yosef oğlu,"],["25","Mattitya oğlu, Amos oğlu, Nahum oğlu, Hesli oğlu, Nagay oğlu,"],["26","Mahat oğlu, Mattitya oğlu, Şimi oğlu, Yosek oğlu, Yoda oğlu,"],["27","Yohanan oğlu, Reşa oğlu, Zerubbabil oğlu, Şealtiel oğlu, Neri oğlu,"],["28","Malki oğlu, Addi oğlu, Kosam oğlu, Elmadam oğlu, Er oğlu,"],["29","Yeşu oğlu, Eliezer oğlu, Yorim oğlu, Mattat oğlu, Levi oğlu,"],["30","Şimon oğlu, Yahuda oğlu, Yosef oğlu, Yonam oğlu, Elyakim oğlu,"],["31","Mala oğlu, Menna oğlu, Mattata oğlu, Natan oğlu, David oğlu,"],["32","Yişay oğlu, Ovet oğlu, Boaz oğlu, Salmon oğlu, Nahşon oğlu,"],["33","Amminadav oğlu, Aram oğlu, Hetsron oğlu, Peres oğlu, Yahuda oğlu,"],["34","Yakov oğlu, İshak oğlu, Avraham oğlu, Terah oğlu, Nahor oğlu,"],["35","Seruk oğlu, Reu oğlu, Pelek oğlu, Ever oğlu, Şelah oğlu,"],["36","Kenan oğlu, Arpakşat oğlu, Sam oğlu, Noa oğlu, Lemek oğlu,"],["37","Metuşelah oğlu, Hanok oğlu, Yeret oğlu, Mahalalel oğlu, Kenan oğlu,"],["38","Enoş oğlu, Şit oğlu, Adem oğlu, Tanrı Oğlu’ydu."]],4:[["1","Kutsal Ruh’la dolu olarak Yarden'den dönen Yeşua, Ruh tarafından çöle yöneltildi."],["2","Kırk gün boyunca İblis tarafından denendi. O günlerde hiçbir şey yemedi. Sonra onlar tamamlanınca, acıktı."],["3","İblis O’na, “Eğer Tanrı’nın Oğlu’ysan, şu taşa ekmek olsun diye buyur” dedi."],["4","Yeşua ona karşılık verip şöyle dedi, “‘İnsan yalnız ekmekle yaşamaz, ama Tanrı’nın her sözüyle yaşar’ diye yazılmıştır”"],["5","İblis Yeşua’yı yüksek bir dağa çıkardı. O’na bir anda dünyanın bütün krallıklarını gösterdi."],["6","O’na, “Bütün bunların yönetimini ve onların görkemini sana vereceğim” dedi. “Çünkü bunlar bana teslim edildi ve ben dilediğime veririm."],["7","Bu nedenle bana taparsan, hepsi senin olacak” dedi."],["8","Yeşua ona şu karşılığı verdi: “Çekil önümden Şeytan! Çünkü şöyle yazılmıştır: ‘Tanrın Efendi’ye tapacak ve yalnız O’na hizmet edeceksin.’”"],["9","İblis O’nu Yeruşalem’e götürüp tapınağın tepesine çıkardı. O’na şöyle dedi: “Eğer Tanrı’nın Oğlu’ysan, kendini buradan aşağı at."],["10","Çünkü şöyle yazılmıştır: ‘Tanrı seni korumaları için meleklerine buyruk verecek.’"],["11","Ve, ‘Ayağın bir taşa çarpmasın diye seni elleri üzerinde taşıyacaklar.’”"],["12","Yeşua ona şöyle karşılık verdi: “’Tanrın Efendi’yi denemeyeceksin’ diye buyrulmuştur.”"],["13","İblis her sınanmayı tamamladıktan sonra bir süreliğine O’nun yanından ayrıldı."],["14","Yeşua, Ruh’un gücüyle Galile’ye döndü. O’nunla ilgili haberler bütün bölgeye yayıldı."],["15","Onların havralarında öğretiyor, herkes tarafından övülüyordu."],["16","Yeşua büyüdüğü Nazaret kentine geldi. Şabat Günü her zaman olduğu gibi havraya gitti. Kutsal Yazılar’ı okumak üzere ayağa kalktı."],["17","O’na Peygamber Yeşaya’nın Kitabı verildi. Kitabı açtı ve şu sözlerin yazılı olduğu yeri buldu:"],["18","“Efendi’nin Ruhu üzerimdedir. Çünkü O, yoksullara Müjde’yi duyurmak için beni meshetti. Kırık yüreklileri iyileştirmek, tutsakların salıverileceklerini, körlerin gözlerinin açılacağını duyurmak için, ezilenleri kurtarmak,"],["19","ve Efendi’nin uygun yılını ilan etmek için beni gönderdi.”"],["20","Kitabı kapattı, görevliye geri verip oturdu. Havradakilerin hepsi gözlerini O’na dikti."],["21","Yeşua onlara, “Duyduğunuz bu Yazı bugün yerine gelmiştir” diye anlatmaya başladı."],["22","Herkes O’nun hakkında tanıklık etti ve ağzından çıkan lütufkâr sözlere şaştı. Kendi aralarında, “Yosef’in oğlu değil mi bu?” diyorlardı."],["23","Onlara şöyle dedi: “Şüphesiz bana şu özdeyişi diyeceksiniz: ‘Ey hekim, kendini iyileştir! Kafernahum’da yapıldığını duyduğumuz şeyleri, burada kendi memleketinde de yap.’”"],["24","Yeşua şöyle devam etti: “Size doğrusunu söyleyeyim, hiçbir peygamber kendi memleketinde kabul görmez."],["25","Ama size doğrusunu söyleyeyim, Eliya'nın günlerinde İsrael'de bir çok dul kadın vardı; göğün üç yıl altı ay kapandığı ve bütün ülkede büyük kıtlık olduğu zaman,"],["26","Eliya bunlardan hiçbirine gönderilmedi. Yalnız Sayda bölgesinin Sarefat Kenti’nde bulunan bir dul kadına gönderildi."],["27","Peygamber Elişa’nın zamanında İsrael’de pek çok cüzamlı vardı. Ama yalnız Suriyeli Naaman dışında bunlardan hiçbiri iyileştirilmedi.”"],["28","Havradakiler bu sözleri duyunca büyük bir öfkeyle doldular."],["29","Ayağa kalkıp O’nu kentten dışarı çıkardılar. O’nu uçurumdan aşağı atmak için kentin kurulduğu tepenin yamacına götürdüler."],["30","Ama Yeşua aralarından geçip gitti."],["31","Yeşua Galile’nin bir kenti olan Kafernahum’a geldi. Şabat Günü onlara öğretiyordu."],["32","Sözlerinde yetki olduğu için öğretişine şaştılar."],["33","Havrada bir adam vardı, kendisinde kirli bir iblis ruhu vardı."],["34","Yüksek sesle, “Ey Nazaretli Yeşua! Seninle ne işimiz var? Bizi yok etmek için mi geldin? Senin kim olduğunu biliyorum, Tanrı’nın Kutsalı’sın!” diye bağırdı."],["35","Yeşua, “Sessiz ol, ondan çık!” diyerek onu azarladı. İblis adamı onların ortasında yere vurup, ona hiçbir zarar vermeden içinden çıktı."],["36","Herkesin üzerine bir şaşkınlık geldi. Birbirlerine, “Bu nasıl söz? Güç ve yetkiyle kirli ruhlara buyruk veriyor, onlar da çıkıyor!” diyorlardı."],["37","Yeşua’yla ilgili haberler bütün yöreye yayıldı."],["38","Yeşua havradan çıkıp Simon’un evine gitti. Simon’un kaynanası yüksek ateş içinde hastaydı. Ona yardım etmesi için kendisine yalvardılar."],["39","Yeşua kadının başucunda durup ateşi azarladı, ateş de kadını terk etti. Kadın hemen ayağa kalkıp onlara hizmet etti."],["40","Güneş batarken, çeşitli hastalıklara yakalanmış olanların hepsini O’na getirdiler. Yeşua ellerini onların her birinin üzerine koydu ve onları iyileştirdi."],["41","İblisler de, “Sen Tanrı’nın Oğlu Mesih'sin!” diyerek çığlık atarak birçoklarının içinden çıkıyordu. Ama Yeşua onları azarlayarak konuşmalarına izin vermiyordu. Çünkü O’nun Mesih olduğunu biliyorlardı."],["42","Gün ağarınca Yeşua oradan ayrılıp ıssız bir yere çekildi. Kalabalıklar O’nu arıyordu. O’na geldiklerinde yanlarından ayrılmasın diye O’nu tutmak istediler."],["43","Yeşua onlara, “Tanrı’nın Krallığı'yla ilgili Müjde’yi başka kentlerde de duyurmam gerek. Bu nedenle gönderildim’’ dedi."],["44","Galile’deki havralarda Müjde’yi duyuruyordu."]],5:[["1","Yeşua Ginnesar Gölü’nün kıyısında duruyordu. Kalabalık Tanrı sözünü dinlemek için O’nun çevresine üşüşmüştü."],["2","Yeşua deniz kıyısında duran iki tekne gördü. Balıkçılar teknelerinden inmiş ağlarını yıkıyorlardı."],["3","Yeşua teknelerden birisine bindi, o da Simon'undu. Ondan kıyıdan biraz açılmasını istedi. Oturup halka tekneden öğretti."],["4","Konuşmasını bitirince Simon’a, “Derinlere açılın, balık tutmak için ağlarınızı atın” dedi."],["5","Simon O’na şöyle yanıt verdi: “Efendim, bütün gece çabaladık, hiçbir şey tutamadık; ama senin sözün uyarınca ağları salacağım.”"],["6","Bunu yaptıklarında o kadar çok balık yakaladılar ki, ağları yırtılıyordu."],["7","Gelip kendilerine yardım etmeleri için öteki teknedeki ortaklarına işaret ettiler. Onlar da geldiler ve her iki tekneyi de balıkla doldurdular. Öyle ki, tekneler batmaya başladı."],["8","Ama Simon Petrus bunu görünce Yeşua’nın dizlerine kapanıp, “Efendimiz benden uzak dur, çünkü ben günahkâr bir adamım” dedi."],["9","Çünkü kendisi ve yanındakiler, tutmuş oldukları balıkların şaşkınlığı içindeydiler."],["10","Simon’un ortakları olan Zebedi oğulları Yakov ve Yuhanna da öyle. Yeşua, Simon’a, “Korkma. Bundan böyle canlı insan tutacaksın.” dedi."],["11","Teknelerini kıyıya çektiler. Her şeyi bırakıp O'nun ardından gittiler."],["12","Yeşua kentlerden birindeyken, işte, cüzamla dolu bir adam geldi. Adam Yeşua’yı görünce yüzüstü yere kapandı. O’na, “Efendimiz, istersen beni temiz kılabilirsin” diyerek yalvardı."],["13","Yeşua elini uzattı ve ona dokunup, “İsterim. Temiz ol!” dedi. Hemen cüzam onu terk etti."],["14","Yeşua ona kimseye söyleme diye buyurdu. “Git kendini kâhine göster ve temizliğin hakkında onlara tanıklık olsun diye, Moşe’nin buyurduğu sunuları sun” dedi."],["15","Ama Yeşua’yla ilgili haber daha çok çevreye yayıldı. O’nu dinlemek, hastalıklarından iyileştirilmek için büyük kalabalıklar toplanıyordu."],["16","Ama kendisi ıssız yerlere çekilip dua ediyordu."],["17","O günlerden birinde Yeşua öğretirken, Galile’nin ve Yahudiye’nin bütün köylerinden ve Yeruşalem’den gelen Ferisiler ve Kutsal Yasa öğretmenleri O’nun çevresinde oturuyordu. Efendi’nin gücü onları iyileştirmek için O'nunla birlikteydi."],["18","İşte, adamlar döşek üzerinde felçli bir adam getirdiler. Felçli adamı içeri sokup Yeşua’nın önüne yatırmaya çalışıyorlardı."],["19","Ama kalabalık nedeniyle onu içeri sokmanın bir yolunu bulamayınca dama çıktılar. Çatıyı kaldırıp yatağıyla birlikte onu Yeşua’nın önüne sarkıttılar."],["20","Yeşua onların imanını görünce, “Ey adam, günahların bağışlandı” dedi."],["21","Yazıcılar ve Ferisiler tartışmaya başlayıp, “Küfreden bu adam da kim? Tanrı dışında günahları kim bağışlayabilir?” dediler."],["22","Onların ne düşündüğünü bilen Yeşua onlara şöyle karşılık verdi: “Neden yüreğinizde böyle düşünüyorsunuz?"],["23","Hangisi daha kolay, ‘Günahların sana bağışlandı’ demek mi, yoksa ‘Kalk ve yürü’ demek mi?"],["24","Ama İnsanoğlu’nun yeryüzünde günahları bağışlamaya yetkisi olduğunu bilesiniz diye,” felçliye, “Sana söylüyorum, kalk, döşeğini toplayıp evine git!” dedi."],["25","Adam onların önünde hemen ayağa kalktı. Üzerinde yattığı döşeği kaldırdı ve Tanrı’yı yücelterek evine gitti."],["26","Herkesi şaşkınlık sardı. Tanrı’yı yücelttiler. Korku içinde, “Bugün garip şeyler gördük” dediler."],["27","Bu şeylerden sonra Yeşua çıktı, vergi toplama yerinde oturan Levi adında bir vergi görevlisini gördü. Ona, “Ardımdan gel!” dedi."],["28","O da her şeyi bırakıp, Yeşua’nın ardından gitti."],["29","Levi Yeşua için evinde büyük bir şölen düzenledi. Bir çok vergi görevlileriyle başka kişilerden oluşan büyük bir kalabalık onlarla birlikte sofradaydı."],["30","Yazıcılar ve Ferisiler, öğrencilerine karşı, “Niçin vergi görevlileriyle ve günahkârlarla birlikte yiyip içiyorsunuz?” diye homurdandılar."],["31","Yeşua onlara şu karşılığı verdi: “Sağlamların değil, hastaların hekime ihtiyacı vardır."],["32","Ben doğru kişileri değil, günahkârları tövbeye çağırmaya geldim.”"],["33","O’na, “Neden Yuhanna’nın öğrencileri sık sık oruç tutup dua ediyorlar? Aynı şekilde Ferisiler’in öğrencileri de. Ama seninkiler yiyip içiyorlar!” dediler."],["34","Onlara, “Güvey aralarındayken konukları hiç oruç tutturabilir misiniz?” dedi."],["35","“Ama güveyin yanlarından alınacağı günler gelecek. O zaman onlar o günlerde oruç tutacaklar.”"],["36","Yeşua onlara bir de benzetme anlattı. “Hiç kimse yeni bir giysiden bir parçayı yırtıp eski bir giysinin üzerine yamamaz. Yoksa hem yeni giysi yırtılır, hem de o giysiden koparılan yama eskisiyle uyuşmaz."],["37","Hiç kimse eski şarap tulumlarına yeni şarap koymaz. Yoksa yeni şarap tulumları patlatır, şarap da dökülür, tulumlar da mahvolur."],["38","Yeni şarabı taze tulumlara koymak gerek. Böylece ikisi de korunabilir."],["39","Hiç kimse eski şarabı içtikten sonra hemen yenisini istemez. Çünkü ‘Eskisi daha iyi’ der.”"]],6:[["1","Yeşua birinciden sonraki ikinci Şabat'ta buğday tarlalarından geçiyordu. Öğrencileri başakları koparıyor, avuçlarında ufalayıp yiyorlardı."],["2","Ama Ferisiler’den bazıları onlara, “Şabat Günü Yasa’ya uygun olmayanı neden yapıyorsunuz?” dediler."],["3","Yeşua onlara karşılık verip dedi: “David’le yanındakiler acıkınca ne yaptığını hiç okumadınız mı?"],["4","Tanrı’nın evine girdi, yalnızca kâhinler dışında yemesi yasak olan sergi ekmeklerini alıp yedi ve yanındakilere de verdi.”"],["5","Onlara, “İnsanoğlu Şabat'ın Efendisi’dir” dedi."],["6","Başka bir Şabat'ta da Yeşua havraya girip öğretti. Orada sağ eli kurumuş bir adam vardı."],["7","Yeşua’yı suçlu çıkaracak bir neden bulabilmek için yazıcılarla Ferisiler, Şabat'ta iyileştirip iyileştirmeyeceğini görmek için O'nu gözlüyorlardı."],["8","Ne var ki, Yeşua onların düşüncelerini biliyordu. Eli sakat adama, “Kalk, orta yerde dur” dedi. O da kalkıp durdu."],["9","Sonra Yeşua onlara, “Söyleyin” dedi. “Size bir şey soracağım, Yasa’ya göre Şabat'ta iyilik yapmak mı, yoksa kötülük yapmak mı doğrudur? Hayat kurtarmak mı yoksa öldürmek mi?”"],["10","Etrafındakilerin hepsine baktıktan sonra adama, “Elini uzat” dedi. Adam elini uzattı ve öteki gibi eli eski haline döndü."],["11","Onlar ise öfkeyle doldular. Kendi aralarında Yeşua’ya ne yapabileceklerini konuşuyorlardı."],["12","Yeşua o günlerde dua etmek için bir dağa çıktı. Bütün geceyi Tanrı’ya dua ederek geçirdi."],["13","Gündüz olunca öğrencilerini yanına çağırdı, içlerinden on ikisini seçti. Onlara elçiler adını verdi."],["14","Petrus adını da verdiği Simon, onun kardeşi Andreas, Yakov, Yuhanna, Filipus, Bartalmay,"],["15","Matta, Tomas, Alfay oğlu Yakov, Yurtsever diye tanınan Simon,"],["16","Yakov oğlu Yahuda ve hain olan Yahuda İskariot."],["17","Yeşua onlarla birlikte aşağıya inip düzlük bir yerde durdu. Öğrencilerinden oluşan bir kalabalık ve bütün Yahudiye ve Yeruşalem’den ve Sur ve Sayda kıyılarından O’nu dinlemeye ve hastalıklarından iyileştirilmeye gelen çok sayıda insan da oradaydı."],["18","Kirli ruhlar yüzünden sıkıntı çekenler de iyileştiriliyordu."],["19","Kalabalıktaki herkes O’na dokunmaya çalışıyordu. Çünkü O’ndan çıkan bir güç herkesi iyileştiriyordu."],["20","Yeşua gözlerini öğrencilerine kaldırdı ve şöyle söyledi: “Ne mutlu yoksul olanlara, çünkü Tanrı’nın Krallığı sizindir."],["21","Ne mutlu şimdi aç olanlara, çünkü doyurulacaksınız. Ne mutlu şimdi ağlayanlara, çünkü güleceksiniz."],["22","İnsanoğlu uğruna, insanlar sizden nefret ettikleri, dışlayıp aşağıladıkları, ve adınızı kötüledikleri zaman ne mutlu size."],["23","O gün sevinin ve coşkuyla sıçrayın, çünkü işte, gökteki ödülünüz büyüktür. Onların da ataları peygamberlere aynı şeyi yaptılar."],["24","Ama vay halinize ey zenginler! Çünkü tesellinizi aldınız."],["25","Vay halinize, ey şimdi tok olanlar, çünkü aç kalacaksınız. Vay halinize, şimdi gülenler, çünkü yas tutup ağlayacaksınız."],["26","İnsanlar sizin hakkınızda iyi konuştukları zaman vay halinize, çünkü onların ataları da sahte peygamberlere aynı şeyi yaptılar.”"],["27","“Ama siz beni dinleyenlere şunu söylüyorum: Düşmanlarınızı sevin, sizden nefret edenlere iyilik yapın."],["28","Size lanet edenleri kutsayın ve size kötü davrananlar için dua edin."],["29","Bir yanağınıza vurana öbürünü de çevirin. Ceketinizi alandan, gömleğinizi de esirgemeyin."],["30","Sizden dileyen herkese verin, malınızı alandan geri istemeyin.”"],["31","“İnsanların size nasıl yapmasını istiyorsanız, siz de onlara öyle yapın."],["32","Eğer sizi sevenleri severseniz, bu size ne kazandırır? Çünkü günahkârlar bile kendilerini sevenleri severler."],["33","Eğer size iyilik edenlere iyilik ederseniz, bu size ne kazandırır ? Çünkü günahkârlar bile aynısını yapar."],["34","Eğer geri almayı umduğunuz kişilere ödünç verirseniz, bu size ne kazandırır? Günahkârlar bile geri almayı umarak günahkârlara ödünç verirler."],["35","Ama siz düşmanlarınızı sevin, iyilik yapın ve ödünç verin, hiçbir şey beklemeden; ödülünüz büyük olacak ve En Yüce Olan’ın çocukları olacaksınız; çünkü O nankörlere ve kötülere karşı şefkatlidir."],["36","Bu nedenle Babanız merhametli olduğu gibi, siz de merhametli olun.”"],["37","“Yargılamayın ki, siz de yargılanmayasınız. Suçlamayın ki, siz de suçlanmayasınız. Serbest bırakın ki, siz de serbest bırakılasınız."],["38","Verin, size de verilecektir. İyice bastırılmış, silkelenmiş ve taşkın, dolu bir ölçekle size verilecektir. Çünkü hangi ölçüyle ölçerseniz, o ölçekle size ölçülecektir.”"],["39","Yeşua onlara bir benzetme söyledi: “Kör köre yol gösterebilir mi? İkisi de çukura düşmez mi?"],["40","Öğrenci öğretmeninden üstün değildir, ancak eğitimini tamamlayan her öğrenci öğretmeni gibi olacaktır."],["41","Neden kardeşinin gözündeki çöpü görürsün de kendi gözündeki direği düşünmezsin?"],["42","Ya da kendi gözündeki direği kendin görmezken, kardeşine nasıl olur da, ‘Kardeş, izin ver gözündeki çöpü çıkarayım’ dersin? Ey ikiyüzlü! Önce kendi gözündeki direği çıkar, o zaman kardeşinin gözündeki çöpü çıkarmak için daha iyi görebilirsin."],["43","Çünkü iyi ağaç yoktur ki, kötü meyve versin, ya da yine kötü ağaç yoktur ki, iyi meyve versin."],["44","Her ağaç kendi meyvesinden tanınır. Çünkü dikenli bitkilerden incir toplamazlar, çalıdan da üzüm toplamazlar."],["45","İyi insan yüreğindeki iyi hazinesinden iyilik, kötü insan yüreğindeki kötü hazinesinden kötülük çıkarır. Çünkü yürekten taşanı ağzı söyler.”"],["46","“Neden bana ‘Efendi, Efendi’ diyorsunuz da, söylediğim şeyleri yapmıyorsunuz?"],["47","Bana gelen, sözlerimi duyan ve onları yapan her insanın kime benzediğini size göstereyim."],["48","O kişi, ev yaparken toprağı derin kazıp, temelini kaya üzerine atan adama benzer. Sel gelince kabaran ırmak o eve saldırdı ama onu sarsamadı. Çünkü ev kaya üzerinde kurulmuştu."],["49","Ama sözlerimi duyup da yapmayan kişi, evini toprak üzerine temelsiz kurmuş adama benzer. Kabaran ırmak saldırınca ev hemen çöker. O evin yıkılışı da büyük oldu.”"]],7:[["1","Yeşua, halkın önünde konuşmasını bitirdikten sonra Kafernahum’a gitti."],["2","Bir yüzbaşının çok sevdiği hizmetkârı hastalanmış ve ölüm döşeğindeydi."],["3","Yüzbaşı Yeşua hakkında duyunca, gelip hizmetkârını kurtarsın diye rica için Yahudiler’in ihtiyarlarını O'na gönderdi."],["4","Onlar da gelip ciddiyetle Yeşua’ya yalvardılar. O’na, “Bu adam senin bunu yapmana layıktır” dediler."],["5","“Çünkü ulusumuzu seviyor ve havramızı yaptıran odur.”"],["6","Yeşua onlarla birlikte gitti. Evin yakınına vardığında, yüzbaşı bazı dostlarını yollayıp O’na şöyle dedi: “Efendim, zahmet etme; çatımın altına girmene layık değilim."],["7","Bu nedenle, sana gelmeye de kendimi layık görmedim; yalnızca bir söz söyle, hizmetkârım iyileşecektir."],["8","Çünkü ben de buyruk altında bulunan bir adamım. Altımda askerler var. Birine, ‘Git’ derim, gider; ötekine, ‘Gel’ derim, gelir. Hizmetkârıma, ‘Şunu yap’ derim, yapar.”"],["9","Yeşua bu şeyleri duyunca, ona şaştı. Sonra dönüp kendisini izleyen kalabalığa şöyle dedi: “Size şunu söyleyeyim, İsrael’de bile böyle büyük bir iman bulmadım.”"],["10","Gönderilenler eve döndüklerinde hasta olan hizmetkârı iyileşmiş buldular."],["11","Yeşua bundan kısa bir süre sonra Nain adlı bir kente gitti. Öğrencilerinden birçoğu büyük bir kalabalıkla O’nunla birlikte gitti."],["12","Kentin kapısına yaklaştıklarında işte, ölmüş olan biri çıkarılıyordu; annesinin tek doğan oğluydu, kadın da bir duldu. Kent halkından büyük bir kalabalık kadınla birlikteydi."],["13","Efendi kadını görünce ona acıdı. Ona, “Ağlama” dedi."],["14","Yaklaşıp tabuta dokununca cenazeyi taşıyanlar durdu. “Genç adam, sana söylüyorum, kalk!” dedi."],["15","Ölmüş olan kalkıp oturdu ve konuşmaya başladı. Yeşua onu annesine geri verdi."],["16","Herkesi korku sardı. “Aramızda büyük bir peygamber ortaya çıktı!” diyerek Tanrı’yı yücelttiler. “Tanrı, halkını ziyarete geldi!” diyorlardı."],["17","Yeşua’yla ilgili bu haber bütün Yahudiye’ye ve bütün çevre bölgelere yayıldı."],["18","Yuhanna’nın öğrencileri bütün bu şeyleri ona anlattılar."],["19","Yuhanna, öğrencilerinden ikisini yanına çağırıp, “Gelecek Olan sen misin, yoksa başka birini mi arayalım?” diyerek onları Yeşua’ya gönderdi."],["20","Adamlar Yeşua’nın yanına gelip, “Vaftizci Yuhanna, ‘Gelecek Olan sen misin, yoksa başka birini mi arayalım?’ demek için bizi sana gönderdi dediler.”"],["21","O saatte Yeşua, bir çok hastalıklardan, dertlerden ve kötü ruhlardan birçok kişiyi iyileştirdi, birçok körün gözlerini açtı."],["22","Yeşua yanıt verip onlara, “Gidin gördüklerinizi, duyduklarınızı Yuhanna’ya bildirin” dedi. “Körler görüyor, kötürümler yürüyor, cüzamlılar temizleniyor, sağırlar işitiyor, ölüler diriliyor ve yoksullara Müjde duyuruluyor."],["23","Ne mutlu bende tökezlemek için bir neden bulmayana!”"],["24","Yuhanna’nın ulakları gittikten sonra Yeşua kalabalığa Yuhanna’dan söz etmeye başladı. “Çöle ne görmeye çıktınız? Rüzgârla sallanan bir kamış mı?"],["25","O zaman ne görmeye çıktınız? Yumuşak giysiler giymiş bir adam mı? İşte, zarif giysiler kuşanıp bolluk içinde yaşayanlar kral saraylarında olur."],["26","Öyleyse ne görmeye çıktınız? Bir peygamber mi? Evet, size şunu söyleyeyim, peygamberden daha fazlasıdır."],["27","‘İşte, habercimi önünden gönderiyorum; senin önünde yolunu hazırlayacak’ diye hakkında yazılmış olan budur” dedi."],["28","“Size derim ki, kadından doğanlar arasında Vaftizci Yuhanna’dan daha büyük bir peygamber yoktur, ancak Tanrı’nın Krallığı'nda en küçük olan ondan daha büyüktür.”"],["29","Yuhanna tarafından vaftiz edilen bütün halk ve vergi görevlileri bunu duyunca Tanrı’nın adil olduğunu ilan ettiler."],["30","Ama kendileri Yuhanna tarafından vaftiz edilmemiş olan Ferisiler ve Kutsal Yasa uzmanları, Tanrı’nın öğüdünü reddetmiş oldular."],["31","Yeşua konuşmasını şöyle sürdürdü: “Öyleyse bu kuşağın insanlarını neye benzeteyim? Onlar neye benzerler?"],["32","Çarşı meydanında oturup birbirine şöyle çağıran çocuklara benziyorlar: ‘Size kaval çaldık, ama oynamadınız! Ağıt yaktık, ama ağlamadınız’."],["33","Vaftizci Yuhanna geldiğinde oruç tutup şarap içmedi. Ama siz ona, ‘onda iblis var’ diyorsunuz."],["34","İnsanoğlu geldiğinde yiyip içti. ‘İşte, obur ve ayyaş adam, vergi görevlileriyle günahkârların dostu!’"],["35","Ancak bilgelik, bilgeliğin kendi çocukları tarafından doğrulanır.”"],["36","Ferisiler’den biri Yeşua’yı yemeğe davet etti. Yeşua Ferisi’nin evine girdi ve sofrada oturdu."],["37","İşte, o kentte günahkâr bir kadın vardı. Yeşua’nın Ferisi’nin evinde sofrada oturduğunu öğrenince kaymaktaşından bir kap içinde güzel kokulu bir yağ getirdi."],["38","O'nun ayaklarının yanında arkada durdu, ağlayarak gözyaşlarıyla ayaklarını ıslatmaya başladı. Başının saçıyla ayaklarını sildi, ayaklarını öptü ve üzerine güzel kokulu yağ ile meshetti."],["39","Kendisini davet eden Ferisi bunu görünce kendi kendine, “Bu adam peygamber olsaydı, kendisine dokunan bu kadının kim ve ne tür bir kadın olduğunu, onun bir günahkâr olduğunu bilirdi” dedi."],["40","Yeşua ona, “Simon, sana söyleyecek bir şeyim var” dedi. O da, “Öğretmenim söyle” dedi."],["41","“Bir alacaklının iki borçlusu vardı. Birinin borcu beş yüz dinar, diğerinin borcu elli dinardı."],["42","Ödeyecek güçleri olmadığından, adam ikisini de bağışladı. Bunlardan hangisi onu daha çok sevecektir?”"],["43","Simon, “Sanırım daha çok bağışlanan” diye yanıtladı. Yeşua ona, “Doğru hükmettin” dedi."],["44","Sonra kadına dönüp Simon’a, “Bu kadını görüyor musun? Ben evine girdim, ayaklarım için bana su vermedin. Ama o gözyaşlarıyla ayaklarımı ıslattı, saçlarıyla da sildi."],["45","Sen beni öpmedin. Ama bu kadın eve girdiğimden beri ayaklarımı öpüp duruyor."],["46","Sen başıma yağla meshetmedin, ama o ayaklarımı güzel kokulu yağla meshetti."],["47","Bu nedenle sana derim ki, onun çok olan günahları bağışlanmıştır. Çok sevmesinin nedeni budur. Ama az bağışlanan, az sever” dedi."],["48","Yeşua kadına, “Günahların bağışlandı” dedi."],["49","O’nunla birlikte sofrada oturanlar kendi kendilerine, “Günahları bile bağışlayan bu adam kim?” diye konuşmaya başladılar."],["50","Kadına, “İmanın seni kurtardı, esenlik içinde git” dedi."]],8:[["1","Kısa bir süre sonra, Yeşua köy kent dolaşarak Tanrı Krallığı'nın müjdesini duyuruyor ve onu getiriyordu. Onikiler de kendisiyle birlikteydi."],["2","Kötü ruhlardan ve hastalıklarından kurtulmuş olan bazı kadınlar vardı: Kendisinden yedi iblis çıkmış olan Magdalalı denilen Mariyam,"],["3","Hirodes’in kâhyası Kuza’nın karısı Yohanna, Suzanna ve daha birçok kadın Yeşua’yla birlikteydi, bunlar, mallarıyla onlara hizmet ediyorlardı."],["4","Büyük bir kalabalık toplanıp her kentten insanlar O'na geldiklerinde Yeşua bir benzetmeyle şöyle dedi:"],["5","“Çiftçinin biri tohum ekmeye çıktı. Ekerken bazıları yol kenarına düştü, ayak altında çiğnenip göğün kuşları onu yuttu."],["6","Bazı tohumlar kaya üzerine düştü, filizlendiğinde susuzluktan kuruyup gitti."],["7","Bazıları dikenlerin arasına düştü. Dikenler onunla büyüdü ve onu boğdu."],["8","Bazıları iyi toprağa düştü ve büyüyüp yüz kat ürün verdi.” Bu şeyleri söyledikten sonra, yüksek sesle, “İşitecek kulağı olan işitsin!” dedi."],["9","Sonra öğrencileri O’na, “Bu benzetme ne anlama geliyor?” diye sordular."],["10","Yeşua, “Tanrı Krallığı'nın sırlarını bilmek size verildi, ama başkalarına benzetmelerle verilir. Öyle ki, ‘Baktıkları halde görmesinler, işittikleri halde anlamasınlar.’"],["11","Benzetme şudur: Tohum Tanrı sözüdür."],["12","Yol kenarındakiler sözü işitenlerdir, o zaman İblis gelir, inanıp kurtulmasınlar diye sözü yüreklerinden alıp götürür."],["13","Kaya üzerindekiler, işitince sözü sevinçle kabul edenlerdir; ama kökleri yoktur. Bir süre inanırlar ve sınanma zamanında saparlar."],["14","Dikenler arasına düşenler, sözü işitenlerdir. Ama bunlar yollarına giderken hayatın kaygılarıyla, zenginlikleriyle ve zevkleriyle boğulur ve olgunlaşıp ürün vermezler."],["15","İyi topraktakiler, dürüst ve iyi yürekli olup, sözü duymuş, onu sıkıca tutan ve sabırla ürün verenlerdir.”"],["16","“Hiç kimse kandil yaktığı zaman onu bir kapla örtmez ya da yatağın altına koymaz; ama içeri girenler ışığı görsün diye onu kandilliğe koyar."],["17","Çünkü açığa çıkmayacak gizli bir şey yoktur. Ne de bilinmeyecek, aydınlığa çıkarılmayacak saklı bir şey vardır."],["18","Bu nedenle, nasıl dinlediğinize dikkat edin. Kimde varsa ona daha fazlası verilecek. Ama kimde yoksa, sahip olduğunu sandığı bile ondan alınacaktır.”"],["19","Annesi ve kardeşleri O’nun yanına geldiler. Ama kalabalık yüzünden kendisine yaklaşamadılar."],["20","Bazıları O'na, “Annenle kardeşlerin dışarıda duruyorlar, seni görmek istiyorlar” diye Yeşua’ya bildirdiler."],["21","Ama O, onlara şu karşılığı verdi: “Annem ve kardeşlerim, Tanrı’nın sözünü işitip onu uygulayanlardır.”"],["22","O günlerin birinde kendisi öğrencileriyle birlikte bir tekneye bindi. Onlara, “Gölün karşı yakasına geçelim” dedi. Böylece kıyıdan açıldılar."],["23","Tekne yol alırken Yeşua uykuya daldı. Gölün üzerine bir fırtına indi. Ciddi bir biçimde su almaya başladılar."],["24","Yanına gelip, “Efendimiz, efendimiz, ölüyoruz!” diyerek O’nu uyandırdılar. Yeşua kalkıp rüzgârı ve suyun hiddetini azarladı. Sular duruldu, ortalık sütliman oldu."],["25","Onlara, “İmanınız nerede?” dedi. Onlar korkup şaşmışlardı. Birbirlerine, “Bu adam kim ki, rüzgârlara ve suya buyruk veriyor, onlar da O’na itaat ediyor!” dediler."],["26","Sonra Galile’nin karşısındaki Gerasalılar’ın ülkesine vardılar."],["27","Yeşua kıyıya ayak basınca, kentten kendisinde iblisler bulunan bir adam O’nu karşıladı. Uzun zamandır sırtına bir şey giymeyen bu adam evde değil, mezarlıklarda yaşıyordu."],["28","Yeşua’yı görünce bağırıp O’nun önünde yere kapandı. Yüksek sesle, “Yeşua, Yüce Tanrı’nın Oğlu, benim seninle ne işim olsun? Yalvarırım bana eziyet etme!” dedi."],["29","Çünkü Yeşua, kirli ruha adamdan çıkmasını buyurmuştu. Kirli ruh sık sık adamı tutuyordu. Adam zincir ve prangaya bağlanarak gözetim altında tutulmasına karşın bağlarını koparıp iblis tarafından ıssız yerlere sürülüyordu."],["30","Yeşua ona, “Adın ne?” diye sordu. “Tümen” dedi. Çünkü adamın içine birçok iblis girmişti."],["31","İblisler kendilerini dipsiz derinliklere gitmelerini buyurmasın diye Yeşua’ya yalvardılar."],["32","Oradaki bayırda otlayan büyük bir domuz sürüsü vardı. İblisler domuzların içine girmelerine izin vermesi için Yeşua’ya yalvardılar. O da onlara izin verdi."],["33","İblisler adamdan çıkıp domuzların içine girdiler. Sürü uçurumdan aşağı koşup denize atlayıp boğuldu."],["34","Ne olduğunu gören domuz çobanları kaçıp kentte ve köylerde bunu anlattılar."],["35","Halk olanları görmek için çıktı. Yeşua’nın yanına geldiklerinde, iblislerden kurtulan adamı giyinmiş ve aklı başında, Yeşua’nın ayakları dibinde otururken buldular ve korktular."],["36","Bunu görmüş olanlar, iblise tutulmuş adamın nasıl kurtulduğunu onlara anlattılar."],["37","Gerasa yöresinden gelen bütün halk Yeşua’nın yanlarından ayrılması için O’na yalvardılar. Çünkü çok fazla korkuyorlardı. O da tekneye binip geri döndü."],["38","İblislerden kurtulan adam Yeşua’yla birlikte gitmek için O’na yalvardı."],["39","Ama Yeşua, “Evine dön ve Tanrı’nın senin için ne büyük şeyler yaptığını anlat” diyerek onu gönderdi. O da gidip, Yeşua’nın kendisi için ne büyük şeyler yaptığını bütün kentte duyurdu."],["40","Yeşua karşı tarafa vardığında kalabalık O’nu hoş karşıladı. Çünkü herkes O’nu bekliyordu."],["41","O sırada havra yöneticisi Yair adında bir adam geldi. Yeşua’nın ayaklarına kapanıp evine gelmesi için yalvardı."],["42","Çünkü on iki yaşındaki kızı, tek doğanı ölmek üzereydi. Yeşua yola çıkmış giderken, kalabalık O’nu sıkıştırıyordu."],["43","On iki yıldan beri kanaması olup, varını yoğunu hekimlere harcamış, ama hiçbirinin iyi edemediği bir kadın,"],["44","Yeşua’nın arkasından gelip giysisinin saçağına dokundu ve hemen kanaması durdu."],["45","Yeşua, “Bana kim dokundu?” dedi. Herkes bunu yadsıyınca, Petrus ve yanındakiler, “Efendimiz, kalabalık seni itiyor ve sıkıştırıyor ve sen, ‘Bana kim dokundu?’ diyorsun” dediler."],["46","Ama Yeşua, “Birisi bana dokundu, çünkü içimden bir gücün çıkıp gittiğini anladım” dedi."],["47","Gizli kalamadığını gören kadın titreyerek geldi ve Yeşua’nın ayaklarına kapandı. Bütün halkın önünde, O’na neden dokunduğunu ve hemen nasıl iyileştiğini anlattı."],["48","Yeşua ona, “Kızım, cesur ol! İmanın seni iyi etti. Esenlik içinde git” dedi."],["49","Yeşua daha konuşurken, havra yöneticisinin evinden biri gelip ona, “Kızın öldü. Artık öğretmeni rahatsız etme” dedi."],["50","Yeşua bunu duyunca ona, “Korkma. Yalnızca iman et ve kızın iyi olacak” dedi."],["51","Yeşua adamın evine vardığında, Petrus, Yuhanna, Yakov ve çocuğun babası ve annesi dışında kimsenin kendisiyle birlikte içeri girmesine izin vermedi."],["52","Herkes ağlıyor ve kızın yasını tutuyordu. Yeşua, “Ağlamayın” dedi. “Kız ölmedi, uyuyor.”"],["53","Kızın öldüğünü bildikleri için O’nunla alay ettiler."],["54","Yeşua hepsini dışarı çıkardı. Kızın elinden tutup yüksek sesle, “Kızım, kalk!” diye seslendi."],["55","Ruhu geri dönünce kız hemen ayağa kalktı. Yeşua, ona yiyecek bir şeyler verilmesini buyurdu."],["56","Kızın anne ve babası şaştılar, ancak Yeşua onlara, bu yapılanları kimseye söylememelerini buyurdu."]],9:[["1","Yeşua Onikiler’i yanına çağırıp onlara bütün iblislerin üzerinde ve hastalıkları iyileştirmek için güç ve yetki verdi."],["2","Onları Tanrı’nın Krallığı'nı duyurmaya ve hastaları iyileştirmeye gönderdi."],["3","Onlara, “Yolculuk için yanınıza hiçbir şey almayın: Ne değnek, ne torba, ne ekmek, ne de para, ne de yedek giysi."],["4","Hangi eve girerseniz, orada kalın ve oradan ayrılın."],["5","Kimler sizi kabul etmezlerse, o kentten ayrılırken onlara uyarı olsun diye ayaklarınızın tozunu silkin” dedi."],["6","Öğrenciler çıkıp köy köy dolaşarak her yerde Müjde’yi duyurup hastaları iyileştirdiler."],["7","Ülkenin dörtte birini yöneten Hirodes, O'nun tarafından bütün yapılanları duydu ve şaşkınlık içindeydi. Bazıları, “Yuhanna ölüler arasından dirildi”,"],["8","bazıları, “Eliya göründü!” ve bazıları da “Eski peygamberlerden biri dirildi” diyordu."],["9","Hirodes, “Yuhanna’nın başını ben kestirdim, ama hakkında böyle şeyler duyduğum bu adam kim?” diyor, Yeşua’yı görmek istiyordu."],["10","Elçiler döndüklerinde, yaptıkları her şeyi Yeşua’ya anlattılar. Yeşua onları ayrı olarak yanına alıp Beytsayda kentinin ıssız bir bölgesine çekildi."],["11","Bunu anlayan kalabalıklar O’nun peşinden gitti. Yeşua onları iyi karşıladı, onlara Tanrı’nın Krallığı'ndan söz etti ve şifaya ihtiyacı olanları iyileştirdi."],["12","Günbatımına doğru Onikiler gelip Yeşua’ya, “Kalabalığı gönder. Çevredeki köylere ve çiftliklere gitsinler. Orada kendilerine kalacak yer ve yiyecek bulsunlar. Çünkü burada ıssız bir yerdeyiz” dediler."],["13","Yeşua, “Onlara siz yiyecek bir şeyler verin” dedi. “Eğer bunca insan için gidip yiyecek satın almazsak, yanımızda beş ekmekle iki balıktan başka bir şey yok” dediler."],["14","Çünkü yaklaşık beş bin kişiydiler. Öğrencilerine, “Halkı ellişer kişilik gruplar halinde oturtun” dedi."],["15","Öyle yaptılar ve hepsini oturttular."],["16","Yeşua beş ekmekle iki balığı aldı, göğe bakıp onları kutsadı, kırdı ve kalabalığın önüne koymaları için öğrencilerine verdi."],["17","Herkes yiyip doydu. Arta kalan parçalardan on iki sepet dolusu kaldırdılar."],["18","Yeşua yalnız başına dua ederken, öğrencileri yakınındaydı. Onlara, “Kalabalıklar benim kim olduğumu söylüyor?” diye sordu."],["19","Öğrenciler, “Vaftizci Yuhanna, ama bazıları Eliya, ötekiler de eski peygamberlerden biri dirilmiş, diyor” dediler."],["20","Yeşua onlara, “Ya siz ben kimim dersiniz?” dedi. Petrus, “Sen Tanrı’nın Mesihi’sin” diye yanıtladı."],["21","Yeşua onları uyarıp bunu kimseye söylememelerini buyurdu."],["22","Onlara, “İnsanoğlu’nun çok acı çekmesi, ihtiyarlar, başkâhinler ve yazıcılar tarafından reddedilmesi, öldürülmesi ve üçüncü gün dirilmesi gereklidir” dedi."],["23","Hepsine, “Ardımdan gelmek isteyen kendini inkâr etsin, çarmıhını yüklenip beni izlesin."],["24","Hayatını kurtarmak isteyen onu yitirecek, ama kim hayatını benim uğruma yitirirse onu kurtaracaktır."],["25","İnsan tüm dünyayı kazanıp da kendi öz varlığını kaybeder ya da zarar ederse bunun kendisine ne faydası olur?"],["26","Çünkü kim benden ve sözlerimden utanırsa, İnsanoğlu da kendi görkemiyle, Babası’nın ve kutsal meleklerin görkemiyle geldiğinde ondan utanacaktır."],["27","Ama size doğrusunu söyleyeyim, burada bulunanlar arasında, Tanrı’nın Krallığı'nı görmeden hiç ölümü tatmayacak olanlar var.”"],["28","Yeşua bu sözleri söyledikten yaklaşık sekiz gün sonra, Petrus, Yuhanna ve Yakov’u yanına alarak dua etmek için dağa çıktı."],["29","Yeşua dua ederken yüzünün görünümü değişti, giysisi göz kamaştırıcı bir beyazlığa büründü."],["30","İşte, iki kişi O’nunla konuşuyordu. Bunlar Moşe’yle Eliya’ydı."],["31","Görkem içinde beliren bu iki kişi, Yeşua’nın yakında Yeruşalem’de gerçekleşecek olan ayrılışını konuşuyorlardı."],["32","Petrus ve onunla birlikte olanların üzerine uyku çökmüştü. İyice uyandıkları zaman Yeşua’nın görkemini ve yanında duran iki adamı gördüler."],["33","Onlar Yeşua’nın yanından ayrılırken Petrus Yeşua’ya, “Efendimiz, bizim için burada bulunmak iyidir!” dedi. “Üç çardak kuralım: Biri sana, biri Moşe’ye, biri de Eliya’ya” dedi. Ne dediğini bilmiyordu."],["34","Petrus bunları söylerken, bir bulut geldi ve onlara gölge saldı. Buluta girerken onlar korktular."],["35","Buluttan gelen bir ses, “Bu benim sevgili Oğlum’dur. O’nu dinleyin!” dedi."],["36","Ses geldiğinde, Yeşua yalnız bulundu. Onlar sustular ve o günlerde görmüş oldukları bu şeylerden kimseye söz etmediler."],["37","Ertesi gün, dağdan indiklerinde, Yeşua’yı büyük bir kalabalık karşıladı."],["38","İşte, kalabalığın içinden bir adam bağırıp, “Öğretmenim, yalvarırım oğluma bir bak!” dedi. “Kendisi benim tek doğan çocuğumdur."],["39","İşte, bir ruh onu tutuyor, birdenbire bağırıyor, onu öyle sarsıyor ki, köpürüyor; ve ondan güçlükle ayrılıp şiddetli bir biçimde onu yaralıyor."],["40","Ruhu kovmaları için öğrencilerine yalvardım, ama yapamadılar.”"],["41","Yeşua, “Ey imansız ve sapmış kuşak! Ne zamana dek sizinle olup size katlanacağım? Oğlunu buraya getir” dedi."],["42","Çocuk Yeşua’ya yaklaşırken iblis onu yere çalıp şiddetle sarstı. Ama Yeşua kirli ruhu azarladı. Çocuğu iyileştirip babasına geri verdi."],["43","Tanrı’nın yüceliği karşısında hepsi şaşkınlık içinde kaldı. Herkes Yeşua’nın yaptığı işlerin şaşkınlığı içindeyken, Yeşua öğrencilerine, şöyle dedi:"],["44","“Şu sözlerimi kulaklarınızda yer edin. Çünkü İnsanoğlu insanların eline teslim edilecek” dedi."],["45","Ama onlar bu sözü anlamadılar. Çünkü sözün anlamı onlardan gizlenmişti. Yeşua’ya bu söz hakkında soru sormaya da korkuyorlardı."],["46","Aralarında içlerinde kimin en üstün olduğu hakkında bir tartışma çıktı."],["47","Yeşua, yüreklerinden geçeni biliyordu. Bir çocuğu aldı ve yanına koydu."],["48","Onlara, “Kim bu çocuğu benim adımla kabul ederse, beni kabul etmiş olur. Beni kabul eden de beni göndereni kabul etmiş olur. Hepinizin arasında en küçük olan, o büyük olacaktır” dedi."],["49","Yuhanna, “Öğretmenimiz, senin adınla iblis kovan birini gördük. Bizimle birlikte senin ardınca gelmediği için ona engel olduk” diye karşılık verdi."],["50","Yeşua ona, “Ona engel olmayın! Bize karşı olmayan bizden yanadır” dedi."],["51","O'nun alınacağı günler yaklaşınca, gitmek üzere yüzünü kararlı bir biçimde Yeruşalem'e doğru çevirdi,"],["52","ve önünden haberciler gönderdi. Onlar da Yeşua için hazırlık yapmak üzere yola çıkıp Samariyalılar’ın bir köyüne girdiler."],["53","Yeşua Yeruşalem’e yöneldiği için Samariyalılar O’nu kabul etmediler."],["54","Öğrencileri Yakov ve Yuhanna bunu görünce, “Efendimiz, Eliya’nın yaptığı gibi bunları yok etmek için bir buyrukla gökten ateş yağdırmamızı ister misin?” dediler."],["55","Ama Yeşua dönüp onları azarladı ve şöyle dedi, “Siz hangi ruhtan olduğunuzu bilmiyorsunuz."],["56","Çünkü İnsanoğlu, insanları yok etmeye değil, ama kurtarmaya geldi.” Başka bir köye gittiler."],["57","Yolda giderlerken, biri Yeşua’ya, “Nereye gidersen git, ardından gelmek istiyorum Efendimiz” dedi."],["58","Yeşua ona, “Tilkilerin inleri, gökyüzünün kuşlarının yuvaları var, ama İnsanoğlu’nun başını yaslayacak bir yeri yok” dedi."],["59","Bir başkasına, “Ardımdan gel!” dedi. Ama o, “Efendimiz, önce gidip babamı gömmeme izin ver” dedi."],["60","Yeşua ona, “Bırak ölüleri, kendi ölülerini kendileri gömsün. Ama sen git ve Tanrı’nın Krallığı'nı duyur” dedi."],["61","Bir başkası da, “Efendimiz, senin ardından gelmek istiyorum. Ama önce izin ver, evimdekilerle vedalaşayım” dedi."],["62","Ama Yeşua ona, “Sabana elini koyup da arkasına bakan biri Tanrı’nın Krallığı'na yakışmaz” dedi."]],10:[["1","Bu şeylerden sonra Efendi başka yetmiş kişi daha görevlendirdi. Onları ikişer ikişer, kendisinin gitmek üzere olduğu her kente ve yere kendi önünden gönderdi."],["2","O zaman onlara, “Gerçekten hasat bol, ama işçiler az. Bu nedenle, hasadın sahibi Efendi’ye dua edin de hasadına işçiler göndersin” dedi."],["3","“Gidin! İşte sizi kuzular gibi kurtların arasına gönderiyorum."],["4","Yanınıza ne para kesesi, ne torba, ne de çarık alın. Yolda giderken kimseyle selamlaşmayın."],["5","Hangi eve girerseniz, önce, ‘Bu eve esenlik olsun’ deyin."],["6","Orada esenlik oğlu varsa, sizin esenliğiniz onun üstünde kalacaktır. Yoksa, size geri dönecektir."],["7","Aynı evde kalın, size ne verirlerse onu yiyip için. Çünkü işçi ücretine layıktır. Evden eve dolaşmayın."],["8","Bir kente girdiğinizde sizi kabul ederlerse, önünüze konulan şeyleri yiyin."],["9","Orada bulunan hastaları iyileştirin ve onlara, ‘Tanrı’nın Krallığı size yaklaştı’ deyin."],["10","Ama bir kentte sizi kabul etmezlerse, caddelerine çıkın ve şöyle deyin:"],["11","‘Şunu bilin ki, Tanrı’nın Krallığı size yaklaştı. Kentinizin ayaklarımıza yapışan tozunu bile size karşı silkiyoruz.’"],["12","Size şunu söyleyeyim, O gün Sodom kentinin durumu o kentten daha katlanılır olacaktır."],["13","“Vay haline, ey Horazin! Vay haline, ey Beytsayda! Çünkü sizde yapılan büyük işler Sur ve Sayda’da yapılmış olsaydı, çoktan çul kuşanıp kül içinde oturmuş, tövbe etmiş olurlardı."],["14","Ama yargı gününde Sur’un ve Sayda’nın durumu sizinkinden daha katlanılır olacaktır."],["15","Ya sen, ey Kafernahum, göğe mi çıkarılacaksın? Hayır, Hades’e indirileceksin."],["16","Kim sizi dinlerse beni dinlemiş olur, kim sizi reddederse beni reddetmiş olur. Kim beni reddederse de beni göndereni reddetmiş olur.”"],["17","Yetmişler sevinçle döndüler. “Efendimiz senin adında iblisler bile bize boyun eğiyor!” dediler."],["18","Yeşua onlara şöyle dedi: “Şeytan’ın gökten yıldırım gibi düştüğünü gördüm."],["19","İşte, size yılanları ve akrepleri ve düşmanın tüm gücünü ayak altında ezmek için yetki verdim. Hiçbir şey size, hiçbir şekilde zarar vermeyecek."],["20","Bununla birlikte, ruhların size boyun eğmesine sevinmeyin, adlarınızın gökte yazılmış olmasına sevinin.”"],["21","O saatte Yeşua Kutsal Ruh’ta coşarak şöyle dedi: “Baba, göğün ve yerin Efendisi! Bunları bilge ve akıllı kişilerden saklayıp küçük çocuklara açtığın için sana şükrediyorum. Evet Baba, sana hoş gelen buydu.”"],["22","Öğrencilerine dönüp, “Bana her şey Babam tarafından teslim edildi. Oğul’un kim olduğunu Baba’dan başka kimse bilemez. Baba’nın kim olduğunu da Oğul’dan ve Oğul’un O’nu açığa vurmak istediği kişilerden başkası bilemez” dedi."],["23","Yine öğrencilerine dönerek özel olarak, “Sizin gördüklerinizi gören gözlere ne mutlu!"],["24","Size şunu söyleyeyim, çok peygamberler, krallar sizin gördüklerinizi görmek istediler, ama görmediler. Sizin duyduklarınızı duymak istediler, ama duymadılar” dedi."],["25","Bir Kutsal Yasa uzmanı Yeşua’yı sınamak amacıyla, “Öğretmenim, sonsuz hayatı miras almak için ne yapmalıyım?” dedi."],["26","Yeşua ona, “Yasa’da ne yazılmıştır? Sen onu nasıl okuyorsun?”"],["27","Kutsal Yasa uzmanı şöyle yanıt verdi: “Tanrın Efendi’ni bütün yüreğinle, bütün canınla, bütün gücünle ve bütün aklınla seveceksin ve komşunu kendin gibi seveceksin.”"],["28","Ona, “Doğru yanıtladın. Bunu yap ve yaşayacaksın” dedi."],["29","Ama kendini haklı çıkarmak isteyerek Yeşua’ya, “Komşum kim benim?” diye sordu."],["30","Yeşua şöyle yanıt verdi: “Bir adam Yeruşalem’den Yeriha’ya iniyordu. Haydutların arasına düştü. Adamı soyup dövdüler, yarı ölü bırakıp gittiler."],["31","Rastlantı sonucu o yoldan bir kâhin iniyordu. Adamı görünce öbür yandan gelip geçti."],["32","Aynı şekilde bir Levili de adamı görünce öbür yandan gelip geçti."],["33","Ama bir Samariyalı yolculuk ederken onun olduğu yere geldi. Onu görünce ona acıdı."],["34","Adamın yanına geldi, yaralarını sardı, yağ ve şarap döktü. Onu kendi hayvanına bindirdi, bir hana götürdü ve onunla ilgilendi."],["35","Ertesi gün ayrılırken iki dinar çıkarıp hancıya verdi. ‘Ona iyi bak’ dedi. ‘Bundan fazla ne harcarsan, döndüğümde sana geri öderim.’"],["36","Şimdi, bu üçünden hangisi haydutların arasına düşen bu adama komşu gibi oldu?”"],["37","Yasa uzmanı, “Ona acıyan” dedi. Sonra Yeşua ona, “Git sen de aynı şekilde yap” dedi."],["38","Yola devam ederlerken, Yeşua bir köye girdi. Marta adında bir kadın O’nu evine kabul etti."],["39","Marta’nın Mariyam adında bir kız kardeşi vardı. Mariyam Efendi’nin ayaklarının dibine oturmuş O’nun sözünü dinliyordu."],["40","Marta ise işlerin çokluğundan ötürü dalgındı. Yeşua’nın yanına gelip, “Efendimiz, kız kardeşimin beni hizmette yalnız bırakmasını umursamıyor musun? Söyle de bana yardım etsin” dedi."],["41","Yeşua ona, “Marta, Marta, sen çok şey için kaygılanıp dertleniyorsun."],["42","Oysa gerekli olan bir şey vardır. Mariyam, kendisinden geri alınmayacak olan iyi payı seçti” dedi."]],11:[["1","Yeşua bir yerde duasını bitirince öğrencilerinden biri O’na, “Efendimiz, Yuhanna’nın öğrencilerine öğrettiği gibi sen de bize dua etmeyi öğret” dedi."],["2","Yeşua onlara, “Dua ettiğinizde şöyle deyin” dedi: “Gökteki Babamız, adın kutsal tutulsun. Krallığın gelsin. Gökte olduğu gibi yeryüzünde de senin isteğin gerçekleşsin."],["3","Günlük ekmeğimizi bize günden güne ver."],["4","Günahlarımızı bağışla, çünkü biz de bize borçlu olan herkesi bağışlıyoruz. Bizi ayartı içine götürme, ama bizi kötü olandan kurtar.”"],["5","Onlara şöyle dedi: “Hangi biriniz gece yarısı bir arkadaşına gidip, ‘Arkadaşım, bana üç somun ödünç ekmek ver."],["6","Çünkü bir arkadaşım yoldan geldi ve önüne koyacak bir şeyim yok’."],["7","Öbürü de içerden, ‘Beni rahatsız etme! Kapı şimdi kapalı, çocuklarım da yanımda yatıyor. Kalkıp sana bir şey veremem’ derdi?"],["8","Size şunu söyleyeyim, arkadaşı olduğu için kalkıp ona istediğini vermese bile, adamın ısrarcılığından ötürü kalkar, ihtiyacı neyse ona verecektir.”"],["9","“Size diyorum ki, dilemeye devam edin, size verilecektir. Aramayı sürdürün, bulacaksınız. Kapıyı çalmaya devam edin, size açılacaktır."],["10","Her dileyen alır, arayan bulur, kapı çalana açılır.”"],["11","“İçinizden hangi baba, kendisinden ekmek isteyen oğluna taş verir? Ya da balık isterse ona balık yerine yılan verir?"],["12","Ya da yumurta isterse akrep verir?"],["13","Sizler kötü olduğunuz halde çocuklarınıza nasıl güzel armağanlar vermeyi biliyorsanız, göksel Babanız’ın kendisinden dileyenlere Kutsal Ruh’u ne kadar daha verecektir?”"],["14","Yeşua adamın birisinden dilsiz bir iblisi kovuyordu. İblis çıkınca dilsiz adam konuştu. Kalabalık şaştı."],["15","Ama içlerinden bazıları, “İblisleri iblislerin önderi Baalzevul aracılığıyla kovuyor” dediler."],["16","Ötekiler de O’nu sınamak amacıyla kendisinden gökten bir belirti istediler."],["17","Onların düşüncelerini bilen Yeşua, “Kendine karşı bölünen her krallık çöl olur. Kendine karşı bölünen ev çöker."],["18","Eğer Şeytan da kendine karşı bölünmüşse, krallığı nasıl ayakta kalır? Çünkü siz diyorsunuz ki, ben iblisleri Baalzevul’un aracılığıyla kovuyorum."],["19","Eğer ben iblisleri Baalzevul aracılığıyla kovuyorsam, sizin çocuklarınız kimin aracılığıyla kovuyor? Bu nedenle onlar sizin yargıçlarınız olacak."],["20","Ama ben iblisleri Tanrı’nın eliyle kovuyorsam, Tanrı’nın Krallığı size kadar gelmiştir.”"],["21","“Tamamen silahlanmış güçlü bir adam, kendi meskenini koruyorsa, malları güvendedir."],["22","Ama daha güçlü biri ona saldırıp onu yendiğinde, güvendiği bütün silahlarını ondan alır ve yağmaladıklarını bölüştürür.”"],["23","“Benden yana olmayan bana karşıdır. Benimle toplamayan dağıtır."],["24","Kirli ruh, insandan çıkınca, rahatlamak için kurak yerlerde dolaşır. Ama bir şey bulamaz. ‘Çıktığım eve geri döneyim’ der."],["25","Döndüğünde, onu süpürülmüş ve düzene koyulmuş bulur."],["26","Sonra gider ve kendisinden daha kötü yedi ruh daha alır. Hep birlikte içeri girip yerleşirler. O adamın son durumu ilkinden beter olur.”"],["27","Yeşua bunları söylerken, kalabalığın içinden bir kadın sesini yükseltip O’na, “Ne mutlu seni taşımış olan rahme, emzirmiş olan memelere!” dedi."],["28","Yeşua, “Tersine, ne mutlu Tanrı’nın sözünü duyup tutanlara!” dedi."],["29","Kalabalık çevresinde toplanınca Yeşua konuşmaya başladı. “Bu kuşak kötü bir kuşaktır. Doğaüstü belirti peşindedir. Ama onlara Yona Peygamberin belirtisinden başka bir belirti verilmeyecektir."],["30","Yona nasıl Ninovalılar için bir belirti olduysa, İnsanoğlu da bu kuşak için öyle olacaktır."],["31","Güney Kraliçesi yargı günü bu kuşağın insanlarıyla birlikte kalkıp onları mahkûm edecek. Çünkü kraliçe, Solomon’un bilgeliğini duymak için dünyanın öbür ucundan kalkıp geldi. İşte, Solomon’dan daha büyük olan buradadır."],["32","Ninova halkı yargı günü bu kuşakla birlikte kalkıp bu kuşağı mahkûm edecek. Çünkü onlar, Yona’nın çağrısı üzerine tövbe ettiler. İşte, Yona’dan daha büyük olan buradadır.”"],["33","“Hiç kimse kandil yakıp onu bodruma ya da sepetin altına koymaz. Ama içeri girenler ışığı görsünler diye onu kandilliğe koyar."],["34","Bedenin ışığı gözdür. Bu nedenle gözün iyiyse, bütün bedenin de ışıkla dolu olur. Ama kötüyse, bedenin de karanlıkla dolu olur."],["35","Bu nedenle, içinizdeki ışığın karanlık olup olmadığına dikkat edin."],["36","Eğer bütün bedenin ışıkla doluysa, hiçbir yanında karanlık yoksa, kandilin parıltısıyla seni aydınlattığı gibi, bedenin tamamen ışıkla dolu olacaktır.”"],["37","Yeşua konuşurken, bir Ferisi O’nu evine yemeğe davet etti. O da içeri girip sofraya oturdu."],["38","Ferisi Yeşua’nın yemekten önce ellerini yıkamadığını görünce şaştı."],["39","Efendi ona şöyle dedi: “Siz Ferisiler kâsenin ve tabağın dışını temizlersiniz, ama içiniz soygunculuk ve kötülükle doludur."],["40","Ey akılsızlar, dışını yapan içi de yapmadı mı?"],["41","Ama içte bulunanlardan yoksullara verin. İşte, o zaman her şey sizin için temiz olacaktır."],["42","Ama vay halinize Ferisiler! Çünkü nanenin, sedef otunun ve her tür sebzenin ondalığını verirsiniz ama adaleti ve Tanrı’nın sevgisini atlarsınız. Ötekini bırakmadan bunları da yapmanız gerekmez miydi?"],["43","Vay halinize ey Ferisiler! Çünkü havralarda en iyi yerleri, çarşı meydanlarında da selamlanmayı seversiniz."],["44","Vay halinize ey yazıcılar ve Ferisiler, ikiyüzlüler! Çünkü siz, üzerinde yürüyenin bilmediği, saklı mezarlar gibisiniz.”"],["45","Kutsal Yasa uzmanlarından biri, “Öğretmenim” dedi. “Bunları söyleyerek bize de hakaret ediyorsun” dedi."],["46","“Sizin de vay halinize, ey Yasa uzmanları! Çünkü insanlara taşınması zor yükler yüklüyorsunuz, kendiniz bu yükleri taşımak için parmağınızı bile kaldırmıyorsunuz."],["47","Vay halinize! Çünkü peygamberlerin anıt mezarlarını yapıyorsunuz ve onları atalarınız öldürdü."],["48","Böylece atalarınızın işlerine tanıklık ediyor, onları da onaylamış oluyorsunuz. Çünkü onlar peygamberleri öldürdüler, siz de onların anıt mezarlarını yapıyorsunuz."],["49","Bu nedenle, Tanrı’nın bilgeliği de şöyle demiştir, ‘Onlara peygamberler ve elçiler göndereceğim. Bazılarını öldürecekler, bazılarına da zulmedecekler.’"],["50","Bu nedenle, dünyanın kuruluşundan bu yana akıtılan bütün peygamberlerin kanı bu kuşaktan sorulacaktır."],["51","Habel’in kanından, sunakla tapınak arasında öldürülen Zekariya’nın kanına dek. Evet, size söylüyorum, bu kuşaktan sorulacaktır."],["52","Vay size ey Yasa uzmanları! Çünkü bilgi anahtarını kaldırdınız. Kendiniz içeri girmediğiniz gibi, girenleri de engellediniz.”"],["53","Yeşua bu şeyleri onlara söyledikten sonra, yazıcılarla Ferisiler, O’na karşı öfkeyle dolmaya başladılar. Bir sürü şeyle ağzını aradılar."],["54","Söyleyeceği bir sözle yakalayıp O'nu suçlu çıkarabilmek için pusuya yattılar."]],12:[["1","Bu arada, halktan binlerce kişi birbirlerini ezercesine toplanıyordu. Yeşua hepsinden önce kendi öğrencilerine şunları anlatmaya başladı: “Ferisiler’in mayasından, yani ikiyüzlülükten sakının."],["2","Üstü kapalı olup da açığa çıkarılmayacak, gizli olup da bilinmeyecek hiçbir şey yoktur."],["3","Bu nedenle karanlıkta söylediğiniz her şey aydınlıkta duyulacak. İç odalarda kulağa söylediğiniz damlardan duyurulacak.”"],["4","“Size söylüyorum dostlarım, bedeni öldüren, ama bundan daha fazlasını yapamayanlardan korkmayın."],["5","Ama kimden korkmanız gerektiğini size haber vereyim. Öldürdükten sonra Gehenna'ya atma gücüne sahip olan Tanrı’dan korkun. Evet, size söylüyorum, O’ndan korkun."],["6","“Beş serçe iki assarya parasına satılmıyor mu? Bunlardan hiçbiri Tanrı tarafından unutulmuş değildir."],["7","Ama başınızdaki saçların bile tamamı sayılıdır. Bu nedenle korkmayın. Siz birçok serçeden daha değerlisiniz."],["8","“Size söylüyorum, insanların önünde beni açıkça kabullenen herkesi, İnsanoğlu da Tanrı’nın melekleri önünde açıkça kabullenecektir."],["9","Ama her kim beni insanların önünde inkâr ederse, Tanrı’nın melekleri önünde inkâr edilecektir."],["10","İnsanoğlu’na karşı bir söz söyleyen herkes bağışlanacak, ama Kutsal Ruh’a küfredenler bağışlanmayacaktır."],["11","Sizi havraların, yöneticilerin ve yetkililerin önüne çıkardıklarında, nasıl ve ne yanıt vereceğiz ya da ne söyleyeceğiz diye kaygılanmayın."],["12","Çünkü Kutsal Ruh o saatte size ne söylemeniz gerektiğini öğretecektir.”"],["13","Kalabalıktan biri Yeşua’ya, “Öğretmenim, kardeşime mirası benimle paylaşmasını söyle” dedi."],["14","Ama Yeşua ona, “Ey adam! Beni üzerinize kim yargıç ya da hakem yaptı?” dedi."],["15","Onlara, “Dikkat edin! Açgözlülükten sakının. Çünkü bir insanın hayatı, sahip olduğu şeylerin bolluğundan oluşmaz.”"],["16","Yeşua onlara bir benzetme anlattı: “Zengin bir adamın toprağı bol ürün verdi."],["17","Adam içinden, ‘Ne yapacağım? Çünkü ürünlerimi koyacak yerim yok’ dedi."],["18","Adam, 'Şunu yapacağım’ dedi. 'Ambarlarımı yıkıp daha büyüklerini yapacağım ve bütün tahılımı ve malımı oraya depolayacağım."],["19","Canıma da, ‘Ey canım yıllarca yetecek kadar bol malın var’ diyeceğim. ‘Rahatına bak, ye, iç ve tadını çıkar.’”"],["20","“Ama Tanrı ona, ‘Ey akılsız! Bu gece canın senden istenecek’ dedi. ‘Hazırladığın bu şeyler kimin olacak?’"],["21","Kendisi için hazine biriktiren ve Tanrı önünde zengin olmayan kişi böyledir.”"],["22","Yeşua öğrencilerine şöyle dedi, “Bunun için size diyorum ki, ne yiyeceğiz diye hayatınız için, ne giyeceğiz diye bedeniniz için kaygılanmayın."],["23","Hayat yiyecekten, beden ise giyecekten daha fazlasıdır."],["24","Kargalara bakın. Ne eker, ne biçerler. Ne kilerleri, ne de ambarları vardır. Tanrı onları doyurur. Siz kuşlardan ne kadar daha değerlisiniz!"],["25","Hanginiz kaygılanmakla boyuna bir arşın ekleyebilir?"],["26","O zaman bu en ufak şeyi bile yapamıyorsanız, neden geri kalanlar için kaygılanıyorsunuz?"],["27","Zambakların, nasıl büyüdüğüne bakın! Ne çalışırlar, ne de iplik eğirirler. Yine de size derim ki, tüm görkemiyle Solomon bile bunlardan biri gibi giyinmiş değildi."],["28","Ey kıt imanlılar, bugün var olup yarın ocağa atılacak olan kır otunu böyle giydiren Tanrı, sizi ne kadar daha giydirecektir?"],["29","Ne yiyeceğinizi, ne içeceğinizi aramayın, ne de kaygılanın."],["30","Çünkü dünya ulusları hep bu şeyleri ararlar. Ama Babanız sizin bu şeylere ihtiyacınız olduğunu bilir."],["31","Siz Tanrı’nın Krallığı'nı arayın, o zaman tüm bu şeyler de size katılacaktır."],["32","Korkma, ey küçük sürü! Çünkü Krallığı size vermek, Babanız'ın kendi iyi arzusuydu."],["33","Sahip olduklarınızı satın, muhtaçlara verin. Kendinize eskimeyen keseler, göklerde tükenmeyen bir hazine biriktirin. Orada hırsız yaklaşmaz, güve de yok etmez."],["34","Hazineniz neredeyse, yüreğiniz de orada olacaktır.”"],["35","“Kuşaklarınız belinizde bağlı kandilleriniz de yanar olsun."],["36","Düğün şöleninden döndüğünde efendilerini hazır bekleyen hizmetkârlar gibi olun. Efendi gelip kapıyı çaldığında, O'na hemen kapıyı açsınlar."],["37","Efendi geldiğinde uyanık bulacağı hizmetkârlara ne mutlu! Size doğrusunu söyleyeyim, kendisi giyinecek, onları sofraya oturtacak ve gelip onlara hizmet edecektir."],["38","Eğer ikinci vakitte ya da üçüncü vakitte gelir, onları böyle bulursa, o hizmetkârlara ne mutlu!"],["39","Ama şunu bilin ki, ev sahibi hırsızın hangi saatte geleceğini bilseydi, gözetler ve evinin soyulmasına izin vermezdi."],["40","Bu nedenle siz de hazır olun, çünkü İnsanoğlu O'nu hiç beklemediğiniz bir saatte gelecektir.”"],["41","Petrus O’na, “Efendimiz, bu benzetmeyi bize mi yoksa herkese mi anlatıyorsun?” dedi."],["42","Efendi şöyle dedi: “O halde efendinin, ev halkına zamanında yiyecek vermesi için başlarına atadığı sadık ve bilge kâhya kimdir?"],["43","Efendisi eve döndüğünde öyle yaparken bulacağı o hizmetkâra ne mutlu!"],["44","Size doğrusunu söyleyeyim, efendisi onu bütün malının üzerine koyacaktır."],["45","Ama eğer o hizmetkâr yüreğinden, ‘Efendimin gelişi gecikiyor’ der kadın ve erkek hizmetkârları dövmeye, yiyip içip sarhoş olmaya başlarsa,"],["46","o hizmetkârın efendisi, onun beklemediği günde ve bilmediği bir saatte gelecek, onu iki parça edip sadakatsizlerle payını verecektir."],["47","Efendisinin isteğini bilip de hazırlık yapmayan ve isteğini yerine getirmeyen hizmetkâr çok dayak yiyecektir."],["48","Ama bilmeden dayağı hak eden şeyler yapan kişi, az dayak yiyecek. Kime çok verilmişse, ondan çok istenecektir ve kime çok emanet edilmişse, kendisinden daha fazla istenecektir.”"],["49","“Ben yeryüzüne ateş atmaya geldim. Keşke o şimdiden tutuşmuş olsaydı."],["50","Ama vaftiz olmam gereken bir vaftizim var. Bu gerçekleşinceye kadar ne kadar da sıkıntı çekiyorum!"],["51","Yeryüzüne barış vermeye mi geldiğimi sanıyorsunuz? Size hayır diyorum, tam tersine bölmeye geldim."],["52","Şu andan itibaren, bir evde beş kişi olacak, üçü ikiye, ikisi üçe karşı bölünecek."],["53","Baba oğula, oğul da babaya karşı bölünecek. Anne kızına, kızı da annesine karşı, kaynana gelinine, gelini de kaynanasına karşı olacaktır.”"],["54","Yeşua kalabalığa şunu da dedi: “Batıdan yükselen bir bulut gördüğünüzde, hemen, ‘Sağanak geliyor’ dersiniz, öyle de olur."],["55","Güney rüzgârı estiğinde, ‘Çok sıcak olacak’ dersiniz, öyle de olur."],["56","Sizi ikiyüzlüler! Yerin ve göğün görünümünü nasıl yorumlayacağınızı bildiğinize göre nasıl oluyor da bu zamanı yorumlayamıyorsunuz?"],["57","Neden neyin doğru olduğuna kendiniz hükmetmiyorsunuz?"],["58","Çünkü davacınızla yargıca giderken, yolda ondan gayretle kurtulmaya çalış. Yoksa seni yargıcın önüne sürükler, yargıç da memura teslim eder, memur da seni zindana atar."],["59","Sana söylüyorum, borcunun son kuruşunu ödemeden oradan asla çıkamayacaksın.”"]],13:[["1","O sırada orada bulunanlardan bazıları, Pilatus’un Galileliler’in kanlarını kendi kurbanlarının kanıyla karıştırdığını O'na bildirdiler."],["2","Yeşua onlara şöyle karşılık verdi: “Sizce böyle acı çeken bu Galileliler’in öteki Galileliler’den daha günahkâr olduğunu mu sanıyorsunuz?"],["3","Size hayır diyorum, ama eğer tövbe etmezseniz hepiniz aynı şekilde yok olacaksınız."],["4","Ya da Şiloah’taki kulenin üzerlerine düştüğü ve öldürdüğü on sekiz insanın, Yeruşalem’de oturan öbür insanların tümünden daha kötü suçlu olduğunu mu sanıyorsunuz?"],["5","Size hayır diyorum, ama eğer tövbe etmezseniz hepiniz aynı şekilde yok olacaksınız.”"],["6","Yeşua şu benzetmeyi anlattı: “Bir adamın bağında incir ağacı dikiliydi. Adam gelip ürün aramış, ama bir şey bulamamış."],["7","Bağcıya, ‘Bak, bu üç yıldır bu incir ağacında ürün aramaya geliyorum, ama hiç bulmadım’ dedi. Ağacı kes. Toprağı neden boşa harcasın?’"],["8","Bağcı, ‘Efendim, ben etrafını kazıyıp gübreleyene dek, bu yıl da bırak’ dedi."],["9","‘Ürün verirse ne iyi, vermezse, onu kesersin.’”"],["10","Yeşua Şabat Günü havralardan birinde öğretiyordu."],["11","İşte, on sekiz yıldır kendisinde hastalık ruhu bulunan bir kadın oradaydı. İki büklüm olmuş, belini hiçbir şekilde doğrultamıyordu."],["12","Yeşua onu görünce çağırdı ve ona, “Kadın, hastalığından kurtuldun” dedi."],["13","Ellerini onun üzerine koydu. Kadın hemen doğruldu ve Tanrı’yı yüceltti."],["14","Yeşua’nın Şabat'ta iyileştirmesine kızan havra yöneticisi kalabalığa şöyle dedi: “İnsanların çalışması gereken gün sayısı altıdır. Bu nedenle o günlerden birinde gelip şifa bulun, Şabat Günü değil!”"],["15","Bu nedenle Efendi ona şu karşılığı verdi: “Sizi ikiyüzlüler! Her biriniz Şabat'ta öküzünü ya da eşeğini yemlikten çözüp suya götürmez misiniz?"],["16","Şeytan’ın on sekiz yıldır bağlı tuttuğu, Avraham’ın kızı olan bu kadın, Şabat Günü bu bağdan çözülmesi gerekmez miydi?”"],["17","O bu şeyleri söyleyince, kendisine karşı gelenlerin hepsi utandı. Kalabalığın hepsi ise O’nun gerçekleştirdiği harika şeyler için sevinç duyuyordu."],["18","Yeşua, “Tanrı’nın Krallığı neye benzer?” dedi. “Onu neye benzeteyim?"],["19","Bir adamın kendi bahçesine alıp ektiği hardal tohumuna benzer. O büyüyüp iri bir ağaç oldu. Göğün kuşları onun dallarında yaşadılar.”"],["20","Yeşua yine, “Tanrı’nın Krallığı neye benzer?"],["21","Bir kadının alıp hepsi mayalanana dek üç ölçek unun içine sakladığı mayaya benzer.”"],["22","Yeşua köy kent dolaşarak Yeruşalem’e doğru yol alıyordu."],["23","Biri ona, “Efendimiz, kurtulanlar az mı olacak?” dedi. Yeşua onlara şöyle dedi:"],["24","“Dar kapıdan girmeye çalışın, size şunu söyleyeyim, birçokları girmeye çalışacak, ama giremeyecek."],["25","Ev sahibi bir kez kalkıp kapıyı kapattıktan sonra siz dışarıdakiler kapıyı çalmaya başlayıp, ‘Efendimiz, bize aç!’ diyeceksiniz. O da size şöyle yanıt verecek, ‘Kim olduğunuzu ve nereden geldiğinizi bilmiyorum.’"],["26","O zaman, ‘Senin önünde yedik, içtik, bizim sokaklarımızda öğrettin’ demeye başlayacaksınız."],["27","O da size şöyle diyecek, ‘Nereden geldiğinizi bilmiyorum. Benden uzak durun, ey kötülük yapanlar!’"],["28","Avraham’ı, İshak’ı, Yakov’u ve bütün peygamberleri Tanrı’nın Krallığı'nda, kendinizi ise dışarı atılmış gördüğünüzde, orada ağlayış ve diş gıcırtısı olacak."],["29","Doğudan, batıdan, kuzeyden ve güneyden gelecekler ve Tanrı’nın Krallığı'nda sofraya oturacaklar."],["30","İşte, sonuncu olan bazıları birinci, birinci olan bazıları da sonuncu olacak.”"],["31","Aynı gün bazı Ferisiler gelip O’na, “Buradan uzaklaş, başka yere git. Çünkü Hirodes seni öldürmek istiyor” dediler."],["32","Onlara, “Gidin ve o tilkiye söyleyin, ‘İşte, bugün ve yarın iblisleri kovup hastaları iyileştireceğim ve üçüncü gün görevimi tamamlayacağım.’"],["33","Yine de bugün, yarın ve ertesi gün yoluma devam etmeliyim. Çünkü bir peygamberin Yeruşalem dışında ölmesi olamaz.”"],["34","“Ey Yeruşalem! Peygamberleri öldüren, kendisine gönderilenleri taşa tutan Yeruşalem! Bir tavuğun civcivlerini kanatları altına toplaması gibi, ben de kaç kez senin çocuklarını öyle toplamak istedim ve sen reddettin!"],["35","İşte, eviniz ıssız kalacak. Size şunu söyleyeyim, ‘Efendi’nin adıyla gelene övgüler olsun!’ deyinceye dek beni görmeyeceksiniz.”"]],14:[["1","Bir Şabat'da Yeşua Ferisiler’in önderlerinden birinin evine ekmek yemeye gitti, onlar O'nu gözlüyorlardı."],["2","İşte, vücudu su toplamış bir adam önündeydi."],["3","Yeşua Kutsal Yasa uzmanlarına ve Ferisiler’e, “Şabat'da iyileştirmek Yasa’ya uygun mudur?” diye konuştu."],["4","Onlar sessiz kaldılar. Yeşua onu alıp iyileştirdi ve gönderdi."],["5","Yeşua onlara, “Hanginizin oğlu ya da öküzü kuyuya düşse, Şabat Günü onu hemen oradan çıkarmaz?” dedi."],["6","Bu şeyler için O’na yanıt veremediler."],["7","Yeşua yemeğe çağrılanların en iyi yerleri nasıl seçtiklerini görünce, onlara şu benzetmeyi anlattı:"],["8","“Biri seni düğün ziyafetine davet ettiğinde, en iyi yere oturma. Olur ya belki senden daha saygın birini de davet etmiştir."],["9","İkinizi de davet eden gelip sana, ‘Bu adama yer ver’ diyebilir. O zaman sen de utançla alt yerde oturmaya başlarsın"],["10","Tersine davet edildiğinde, git en alt yere otur. Öyle ki, seni davet eden geldiğinde, ‘Dostum, yukarı çıkmaz mısın?’ desin. O zaman, seninle sofrada oturanların hepsinin önünde onurlandırılmış olursun."],["11","Kendini yücelten herkes alçaltılacak, kendini alçaltan da yüceltilecektir.”"],["12","Yeşua kendisini davet edene de şöyle dedi, “Bir yemek ya da ziyafet düzenlediğin zaman, arkadaşlarını, kardeşlerini, akrabalarını, zengin komşularını çağırma” dedi. “Yoksa onlar da seni çağırıp iyiliğinin karşılığını verirler."],["13","Bir ziyafet verdiğinde yoksulları, sakatları, topalları, körleri çağır."],["14","Böylece mutlu olursun. Çünkü onların senin iyiliğine karşılık verecek durumları yoktur. Doğru kişiler dirildiğinde sana karşılığı ödenecektir.”"],["15","O’nunla birlikte sofrada oturanlardan biri bunları duyunca, “Tanrı Krallığı'nda ekmek yiyecek insana ne mutlu!” dedi."],["16","Ama Yeşua ona, “Adamın biri büyük bir şölen hazırlayıp birçok insanı davet etti."],["17","Şölen vakti geldiğinde, ‘Gelin, her şey hazır’ demesi için davetlilere hizmetkârını gönderdi."],["18","Hepsi birden özür dilemeye başladı. Birincisi, ‘Bir tarla satın aldım, gidip bir bakmalıyım’ dedi. ‘Lütfen beni hoş gör’ dedi."],["19","Bir diğeri, ‘Beş çift öküz aldım, gidip onları denemeliyim’ dedi. ‘Lütfen beni hoş gör’ dedi."],["20","“Yine bir diğeri, ‘Ben evlendim, bu nedenle gelemem’ dedi."],["21","“Hizmetkâr efendisine gelip bu şeyleri bildirdi. Sonra evin efendisi öfkeyle hizmetkârına, ‘Çabuk kentin meydanlarına ve sokaklarına çık! Yoksulları, sakatları, körleri ve topalları buraya getir’ dedi."],["22","Hizmetkâr, ‘Efendim, buyurduğun gibi yaptım ama hâlâ boş yer var’ dedi."],["23","Efendisi hizmetkârına, ‘Yollara, çitlere koş! Bulduklarını gelmeye zorla, öyle ki evim dolsun’ dedi."],["24","‘Çünkü size şunu söyleyeyim, davet edilen o kişilerin hiçbiri benim yemeğimi tatmayacak. Çünkü çağrılanlar çok, ama seçilenler azdır. ’”"],["25","Büyük bir kalabalık Yeşua’yla birlikte yol alıyordu. Dönüp onlara şöyle dedi:"],["26","“Eğer biri bana gelip de babasının, annesinin, eşinin, çocuklarının, erkek ve kız kardeşlerinin, hatta kendi hayatını bile hiçe saymazsa benim öğrencim olamaz."],["27","Kim çarmıhını yüklenip ardımdan gelmezse, benim öğrencim olamaz."],["28","İçinizden hanginiz bir kule yapmak ister de, onu tamamlayacak kadar parasının olup olmadığını önce oturup hesabını yapmaz?"],["29","Yoksa temel atıp bitiremediğini görenler,"],["30","‘Bu adam bina etmeye başladı, ama bitiremedi’ diyerek onunla alay etmeye başlar."],["31","Ya da hangi kral başka bir kralla savaşta karşı karşıya geldiğinde, önüne yirmi bin askerle çıkan düşmana on bin askerle karşı koyabilir miyim diye önce oturup düşünmez?"],["32","Yoksa diğeri daha çok uzaktayken bir elçi gönderip barış koşullarını sorar."],["33","Bu nedenle, içinizden kim sahip olduğu her şeyden vazgeçmezse, öğrencim olamaz."],["34","Tuz iyidir, ancak tuz tatsızlaşmışsa, ona neyle tat verilebilir?"],["35","Ne toprağa, ne de gübre yığınına uygundur. Dışarı atılır. İşitecek kulakları olan işitsin.”"]],15:[["1","Bütün vergi görevlileriyle günahkârlar Yeşua’yı dinlemek için O’na yaklaşıyorlardı."],["2","Ferisiler ve yazıcılar, “Bu adam günahkârları kabul ediyor ve onlarla birlikte yemek yiyor” diye söyleniyorlardı."],["3","Yeşua onlara bir benzetme anlattı:"],["4","“İçinizden hanginizin, yüz koyunu olur da, bunlardan bir tekini kaybettiğinde, doksan dokuzunu kırda bırakıp kaybolanı buluncaya dek peşine düşmez?"],["5","Onu bulunca, sevinçle omuzlarında taşır."],["6","Eve döndüğünde, arkadaşlarını ve komşularını çağırıp onlara, ‘Benimle birlikte sevinin, çünkü kaybolan koyunumu buldum!’ der."],["7","Size şunu söyleyeyim, bunun gibi gökte, tövbe eden tek bir günahkâr için, tövbe ihtiyacı olmayan doksan dokuz doğru kişi için duyulandan daha çok sevinç duyulur."],["8","Ya da hangi kadının, on drahmi parası olur da birini kaybettiğinde, kandil yakıp evi süpürüp onu buluncaya dek gayretle aramaz?"],["9","Onu bulunca, arkadaşlarını ve komşularını çağırıp, ‘Benimle birlikte sevinin, çünkü kaybettiğim parayı buldum’ der."],["10","Yine size şunu söyleyeyim, bunun gibi Tanrı’nın melekleri önünde de tövbe eden bir günahkâr için sevinç olur.”"],["11","Yeşua, “Bir adamın iki oğlu varmış” dedi."],["12","“İçlerinden küçüğü babasına, ‘Baba, malından payıma düşeni bana ver’ dedi. Baba da varını iki oğlu arasında paylaştırdı."],["13","Birkaç gün sonra, küçük oğul her şeyini toplayıp uzak bir ülkeye gitti. Orada sefahat içinde bir hayat sürerek varını yoğunu çarçur etti."],["14","Hepsini harcadıktan sonra, o ülkede şiddetli bir kıtlık oldu. O da yoksulluk çekmeye başladı."],["15","Gidip o ülkenin vatandaşlarından birinin hizmetine girdi. Adam onu, domuz gütmek üzere tarlalarına gönderdi."],["16","O, domuzların yediği keçiboynuzlarıyla karnını doyurmak istiyordu, ama kimse ona bir şey vermedi."],["17","Kendine gelince şöyle dedi, ‘Babamın ücretli hizmetkârının fazlasıyla yiyeceği var ve ben burada açlıktan ölüyorum!’ dedi."],["18","Kalkıp babamın yanına gideceğim ve ona, ‘Baba, göğe karşı ve senin gözünde günah işledim."],["19","Artık oğlun olarak anılmaya layık değilim. Beni ücretli hizmetkârından biri gibi yap’ diyeceğim.”"],["20","“Kalkıp babasının yanına vardı. Ama o daha uzaktayken babası onu gördü, ona acıdı, koşup boynuna sarıldı ve onu öptü."],["21","Oğul ona, ‘Baba, göğe karşı ve senin gözünde günah işledim’ dedi. ‘Artık oğlun olarak anılmaya layık değilim.’”"],["22","“Ama baba hizmetkârlarına, ‘En iyi giysiyi çıkarıp ona giydirin’ dedi. ‘Parmağına yüzük takın, ayaklarına çarık giydirin."],["23","Besili danayı getirip kesin, yiyelim, eğlenelim."],["24","Bu oğlum ölmüştü, hayata döndü. Kaybolmuştu, bulundu.’ Onlar eğlenmeye başladılar.”"],["25","“Büyük oğlu tarladaydı. Eve yaklaştığında, müzik ve oyun sesleri duydu."],["26","Hizmetkârlardan birini yanına çağırıp neler olduğunu sordu."],["27","Ona, ‘Kardeşin geldi. Baban da sağ salim ona kavuştuğu için besili danayı kesti’ dedi."],["28","Büyük oğul öfkelendi ve içeri de girmek istemedi. Bunun üzerine babası dışarı çıkıp ona yalvardı."],["29","Ama o, babasına, ‘İşte, bunca yıldır sana hizmet ettim. Hiçbir zaman buyruğundan çıkmadım. Ama sen arkadaşlarımla eğlenmem için bana bir oğlak vermedin."],["30","Oysa malını fahişelerle yiyip bitiren şu oğlun gelince, onun için besili danayı kestin.’”"],["31","“Babası ona, ‘Oğlum, sen hep yanımdasın, benim olan her şey senindir’ dedi."],["32","‘Ama sevinip eğlenmek uygun olandı. Çünkü senin bu kardeşin ölmüştü, hayata döndü; kaybolmuştu, bulundu!’”"]],16:[["1","Yeşua öğrencilerine şunları da söyledi: “Zengin bir adamın bir kâhyası vardı. Efendisine malını bu adam çarçur ediyor diye şikayet ettiler."],["2","Efendisi kâhyayı yanına çağırıp, ‘Senin hakkında duyduğum bu nedir? Kâhyalığının hesabını ver. Çünkü sen artık kâhyalık edemezsin’ dedi."],["3","“Kâhya kendi kendine, ‘Efendim kâhyalığı elimden alıyor, ne yapacağım ben? Toprak kazmaya gücüm yok. Dilenmekten de utanırım."],["4","Kâhyalıktan kovulduktan sonra insanların beni evlerine kabul etmeleri için ne yapacağımı biliyorum’ dedi."],["5","Sonra efendisine borcu olanları her birini yanına çağırdı. Birincisine, ‘Efendime ne kadar borcun var?’ dedi."],["6","Adam, ‘Yüz batos yağ’ dedi. Kâhya ona, ‘Borç senedini al, hemen otur ve elli yaz’ dedi."],["7","Sonra bir başkasına, ‘Senin borcun ne kadar?’ dedi. ‘Yüz kor buğday’ dedi. ‘Senedini al ve seksen yaz’ dedi."],["8","“Efendisi, bilgece davrandığı için dürüst olmayan bu kâhyayı övdü. Çünkü bu dünyanın çocukları kendi kuşağında ışığın çocuklarından daha akıllıdır."],["9","Size şunu söyleyeyim, haksızlık mamonu ile kendinize dostlar edinin. Öyle ki, o yok olduğunda sizi ebedi meskenlere kabul etsinler."],["10","Çok azda sadık olan, çokta da sadık olur. Çok azda dürüst olmayan, çokta da dürüst olmaz."],["11","Bu nedenle, eğer haksızlık mamonunda sadık olmamışsanız, gerçek zenginliği size kim emanet eder?"],["12","Başkasının şeylerinde sadık olmadıysanız, kendinizin olsun diye kim size verir?"],["13","Hiçbir hizmetkâr iki efendiye hizmet edemez. Çünkü ya birinden nefret edip diğerini sever, ya da birini tutup diğerini hor görür. Hem Tanrı’ya, hem de Mamon'a hizmet edemezsiniz.”"],["14","Parayı seven Ferisiler de bütün bu şeyleri duyunca Yeşua’yla alay ettiler."],["15","Yeşua onlara şöyle dedi: “Siz, kendini insanların gözünde doğru çıkaranlardansınız, ama Tanrı yüreklerinizi biliyor. Çünkü insanların arasında yüceltilen şeyler, Tanrı gözünde iğrençtir."],["16","Kutsal Yasa ve peygamberler Yuhanna’ya kadardı. O zamandan beri, Tanrı’nın Krallığı müjdeleniyor ve herkes oraya zorla girmeye çalışıyor."],["17","Ama yerin ve göğün geçmesi, Yasa’nın ufak bir noktasının düşmesinden daha kolaydır."],["18","Karısını boşayıp bir başkasıyla evlenen adam zina eder. Kocasından boşanmış bir kadınla evlenen de zina eder.”"],["19","“Varlıklı bir adam vardı. Mor, ince keten giysiler giyer, zevk içinde her gün yaşardı."],["20","Bedeni yaralarla dolu olan Lazar adında yoksul bir adamı onun kapısının önüne götürürlerdi."],["21","Lazar adamın masasından düşen kırıntılarla karnını doyurmak isterdi. Köpekler de gelip onun yaralarını yalardı."],["22","Dilenci öldü ve melekler tarafından Avraham’ın kucağına götürüldü. Sonra zengin adam da öldü ve gömüldü."],["23","Hades’te, ıstırap çeken zengin adam başını kaldırıp uzakta Avraham’ı ve kucağında duran Lazar’ı gördü."],["24","‘Ey Avraham baba, bana merhamet et!’ diye feryat etti. ‘Lazar’ı gönder de, parmağının ucunu suya batırıp dilimi serinletsin! Çünkü bu alevin içinde azap çekiyorum.’”"],["25","“Ama Avraham, ‘Oğlum, hayatın boyunca senin iyi şeyler, Lazar’ın da aynı şekilde kötü şeyler aldığını hatırla. Şimdi o burada teselli ediliyor, sen de azap çekiyorsun."],["26","Bunların hepsinin dışında, aramızda öyle büyük bir uçurum koyulmuş ki, ne buradan oraya, ne de oradan buraya kimse gelebilir’ dedi.”"],["27","“Zengin adam, ‘O zaman baba, senden Lazar’ı babamın evine göndermeni rica ediyorum."],["28","Çünkü beş kardeşim var, Lazar onlara tanıklık etsin ki, onlar da bu işkence yerine gelmesinler.’”"],["29","“Ama Avraham ona, ‘Moşe ve peygamberlere sahipler’ dedi. ‘Onları dinlesinler.’”"],["30","“‘Hayır, Avraham baba, ama ölülerden birisi onlara giderse, tövbe ederler’ dedi.”"],["31","“Avraham da ona, ‘Eğer Moşe’yi ve peygamberleri dinlemezlerse, ölüler arasından biri dirilse bile yine ikna olmazlar’ dedi.”"]],17:[["1","Yeşua öğrencilerine, “Tökezlerin hiç gelmemesi olanaksızdır; ama gelişine aracılık edenin vay haline!” dedi."],["2","Bu küçüklerden birini tökezletmektense, boynuna bir değirmen taşı takılıp denize atılması kendisi için daha iyi olur."],["3","Dikkatli olun! Kardeşin sana karşı günah işlerse, onu azarla. Eğer tövbe ederse onu bağışla."],["4","Sana karşı günde yedi kez günah işler ve yedi kez gelip, ‘Tövbe ediyorum’ derse onu bağışlayacaksın.”"],["5","Elçiler Efendi’ye, “İmanımızı artır” dediler."],["6","Efendi şöyle dedi: “Eğer bir hardal tanesi kadar imanınız olsaydı, şu incir ağacına, ‘Kökünden sökülüp denize dikil’ deseydiniz, o da size itaat ederdi."],["7","Ama içinizden hanginiz çift süren ya da sürüleri güden bir hizmetkârı olur da, tarladan geldiğinde ona, ‘Hemen gel, sofraya otur’ der?"],["8","Bunun yerine ona, ‘Yemeğimi hazırla, güzelce giyin, ben yiyip içerken bana hizmet et. Sonra sen yiyip içersin’ demez mi?"],["9","Hizmetkârına buyurduğu şeyleri yaptığı için ona teşekkür eder mi? Düşüncem hayır."],["10","Siz de aynı şekilde, size buyrulan her şeyi yaptığınız zaman, ‘Biz değersiz hizmetkârlarız. Biz görevimizi yaptık’ deyin.”"],["11","Yeşua Yeruşalem’e doğru giderken Samariya ve Galile sınırlarından geçiyordu."],["12","Bir köye girdiğinde uzakta duran on cüzamlı O’nu karşıladı."],["13","“Efendimiz, Yeşua, bize acı!” diye bağırdılar."],["14","Yeşua onları görünce, “Gidin, kendinizi kâhinlere gösterin” dedi. Adamlar giderken temizlendiler."],["15","İçlerinden biri iyileştiğini görünce yüksek sesle Tanrı’yı yücelterek geri döndü."],["16","Yüzüstü Yeşua’nın ayaklarına kapanıp O’na teşekkür etti. O bir Samariyalı’ydı."],["17","Yeşua, “On kişi temizlenmedi mi? Ama dokuzu nerede?” diye karşılık verdi."],["18","“Tanrı’yı yüceltmek için bu yabancıdan başka geri dönen olmadı mı?”"],["19","Sonra ona, “Kalk, yoluna git, imanın seni iyileştirdi” dedi."],["20","“Ferisiler Tanrı’nın Krallığı ne zaman gelecek?” diye sordular. Yeşua onlara, “Tanrı’nın Krallığı gözle görünür biçimde gelmez” dedi."],["21","“İnsanlar da bak, ‘Burada!’ ya da ‘Bak şurada!’ diyemezler. Çünkü Tanrı’nın Krallığı içinizdedir.”"],["22","Yeşua öğrencilerine şöyle dedi: “İnsanoğlu’nun günlerinden birini görmeyi dileyeceğiniz günler gelecek, ama görmeyeceksiniz."],["23","Onlar size, ‘Bakın, burada!' ya da 'Bakın şurada!’ diyecekler. Gitmeyin, peşlerine düşmeyin."],["24","Çünkü göğün altında, şimşek çaktığında göğü bir ucundan öbür ucuna dek nasıl aydınlatırsa, İnsanoğlu da kendi gününde öyle olacaktır."],["25","Ama önce O’nun çok şeyler çekmesi ve bu kuşak tarafından reddedilmesi gerekiyor."],["26","Noa’nın günlerinde olduğu gibi, İnsanoğlu’nun günlerinde de öyle olacak."],["27","Noa’nın gemiye bindiği güne dek onlar yiyor, içiyor, evleniyor, evlendiriliyordu; ve tufan gelip hepsini yok etti."],["28","Lut’un günlerinde öyle oldu. Onlar yiyip içiyor, satın alıyor, tohum ekiyor, bina ediyorlardı."],["29","Ama Lut’un Sodom’dan çıktığı gün, gökten ateş ve kükürt yağdı ve hepsini yok etti."],["30","İnsanoğlu’nun görüneceği gün de aynı olacaktır."],["31","O gün damda olup da malları evde bulunan, onları almak için aşağı inmesin. Tarlada olan da geri dönmesin."],["32","Lut’un karısını hatırlayın!"],["33","Hayatını kurtarmaya çalışan onu yitirecek, hayatını yitiren ise onu koruyacaktır."],["34","Size şunu söyleyeyim, o gece bir yatakta iki kişi bulunacak; biri alınacak, öteki bırakılacak."],["35","Değirmende birlikte buğday öğüten iki kişi olacak. Biri alınacak ve diğeri bırakılacak.”"],["36",""],["37","Öğrenciler karşılık verip O’na, “Nerede, Efendimiz?” diye sordular. Yeşua, “Leş neredeyse, akbabalar da orada toplanacaklar” dedi."]],18:[["1","Yeşua öğrencilerine, hiç vazgeçmeden, sürekli dua etmeleri gerektiğine dair şu benzetmeyi de anlattı:"],["2","“Bir kentte Tanrı’dan korkmayan, insana saygı duymayan bir yargıç vardı."],["3","O kentte yaşayan dul bir kadın vardı. Sık sık yargıca gelip, ‘Davalımdan hakkımı al!’ diyordu."],["4","Yargıç bir süre istemedi, ancak sonra kendi kendine, ‘Her ne kadar Tanrı’dan korkmaz, insana saygı duymasam da,"],["5","yine bu dul kadın beni rahatsız ettiği için onun hakkını alacağım. Yoksa sürekli gelip beni yıpratacak’ dedi.”"],["6","Efendi şöyle dedi: “Adaletsiz yargıcın ne dediğini dinleyin."],["7","Tanrı onlar için sabırlı olsa da, gece gündüz kendisine yakaran seçilmişlerinin öcünü almayacak mı?"],["8","Size şunu söyleyeyim, onların öcünü çarçabuk alacaktır. Yine de İnsanoğlu geldiği zaman, acaba yeryüzünde iman bulacak mı?”"],["9","Yeşua şu benzetmeyi de kendi doğruluklarına güvenip diğerlerini hor gören bazı kişilere söyledi:"],["10","“İki adam dua etmek için tapınağa çıktı. Bunlardan biri Ferisi, diğeri ise vergi görevlisiydi."],["11","Ferisi ayağa kalkıp kendi kendine şöyle dua etti: ‘Tanrım, diğer insanlar- soyguncular, hak yiyenler, zina edenler- şu vergi görevlisi gibi olmadığım için sana şükrediyorum."],["12","Haftada iki gün oruç tutuyor, tüm kazancımın ondalığını veriyorum.’"],["13","Ama vergi görevlisi, uzakta durup gözlerini bile göğe kaldırmak istemedi. ‘Tanrım, ben günahkâra, merhamet et!’ diyerek göğsünü dövdü."],["14","Size derim ki, öteki değil, bu adam aklanmış olarak evine indi. Çünkü kendini yücelten herkes alçaltılacak, kendini alçaltan ise yüceltilecektir.”"],["15","Yeşua’nın yanına dokunması için bebekleri bile getiriyorlardı. Ama öğrenciler bunu görünce onları azarladılar."],["16","Yeşua onları çağırıp dedi, “Bırakın çocukları, bana gelsinler, onlara engel olmayın! Çünkü Tanrı’nın Krallığı böylelerinindir."],["17","Size doğrusunu söyleyeyim, Tanrı’nın Krallığı'nı küçük bir çocuk gibi kabul etmeyen, ona asla girmeyecektir.”"],["18","Önderlerden birisi Yeşua’ya, “İyi Öğretmenim, sonsuz hayatı miras almak için ne yapmalıyım?” diye sordu."],["19","Yeşua ona şunu sordu, “Bana neden iyi diyorsun? İyi olan yalnız biri var, O da Tanrı’dır."],["20","Buyrukları biliyorsun: ‘Zina etmeyeceksin’, ‘Adam öldürmeyeceksin’, ‘Çalmayacaksın’, ‘Yalan yere tanıklık etmeyeceksin’, ‘Babana ve annene saygı göstereceksin’”"],["21","“Tüm bunları gençliğimden beri tutuyorum” dedi."],["22","Yeşua bunu duyunca ona, “Hâlâ bir eksiğin var. Sahip olduğun her şeyi sat, yoksullara dağıt. O zaman gökte hazinen olur. Sonra gel, beni takip et” dedi."],["23","Adam bu şeyleri duyunca çok üzüldü, çünkü çok zengindi."],["24","Yeşua onun çok üzüldüğünü görünce, “Serveti olanların Tanrı Krallığı'na girmesi ne kadar zor!"],["25","Çünkü devenin iğne deliğinden geçmesi, zengin bir adamın Tanrı Krallığı'na girmesinden daha kolaydır” dedi."],["26","Bunu duyanlar, “Öyleyse kim kurtulabilir?” dediler."],["27","Yeşua, “İnsanlar için mümkün olmayan şeyler, Tanrı için mümkündür” dedi."],["28","Petrus, “Bak, biz her şeyimizi bırakıp senin ardından geldik” dedi."],["29","Onlara şöyle dedi: “Size doğrusunu söyleyeyim, Tanrı’nın Krallığı uğruna evini, karısını, kardeşlerini, ana-babasını ya da çocuklarını bırakıp da"],["30","bu çağda bunların kat kat fazlasına ve gelecek dünyada sonsuz hayata kavuşmayacak hiç kimse yoktur” dedi."],["31","Yeşua Onikiler’i bir kenara çekip onlara şöyle dedi: “İşte, Yeruşalem’e çıkıyoruz. Peygamberler aracılığıyla İnsanoğlu hakkında yazılanların hepsi tamamlanacak."],["32","Çünkü O, öteki ulusların eline teslim edilecek. O’nunla alay edip aşağılayacaklar, üzerine tükürecekler."],["33","O’nu kırbaçlayıp öldürecekler. O üçüncü gün dirilecektir.”"],["34","Onlar bu şeylerin ne anlama geldiğini anlamadılar. Bu sözün anlamı onlardan gizlenmiş olduğu için söylenenleri anlamadılar."],["35","Yeşua Yeriha’ya yaklaşırken, kör bir adam yol kenarında oturmuş dileniyordu."],["36","Yanından geçen kalabalığın sesini duyunca, “Bunun anlamı nedir?” diye sordu."],["37","Ona Nazaretli Yeşua’nın geçtiğini bildirdiler."],["38","Adam, “Ey David Oğlu Yeşua, bana acı!” diye bağırdı."],["39","Önden gidenler sussun diye onu azarladılar. Ama o daha da çok, “Ey David Oğlu, halime acı!” diyerek bağırdı."],["40","Yeşua durdu ve adamın kendisine getirilmesini buyurdu. Adam yaklaşınca Yeşua,"],["41","“Ne yapmamı istiyorsun?” diye sordu. O da, “Efendimiz, gözlerim yeniden görsün” dedi."],["42","Yeşua ona, “Gözlerin görsün. İmanın seni iyileştirdi” dedi."],["43","Adam hemen gördü ve Tanrı’yı yücelterek Yeşua’nın ardından gitti. Bunu görünce bütün halk Tanrı’yı yüceltti."]],19:[["1","Yeşua Yeriha’ya girip geçiyordu."],["2","Zakkay adında bir adam vardı. Kendisi vergi görevlilerinin başıydı ve zengindi."],["3","Zakkay, Yeşua’nın nasıl biri olduğunu görmek istiyor, ama kısa boylu olduğu için kalabalıktan dolayı göremiyordu."],["4","Yeşua’yı görebilmek için önden koşup bir incir ağacına tırmandı. Çünkü Yeşua o yoldan geçecekti."],["5","Yeşua o yere geldiğinde yukarı bakıp onu gördü. Ona, “Zakkay, acele et aşağıya in! Çünkü bugün senin evinde kalmam gerekiyor” dedi."],["6","Zakkay aceleyle aşağı indi ve sevinçle Yeşua’yı evine kabul etti."],["7","Bunu gören herkes söylenmeye başladı: “Gidip bir günahkâra konuk oldu!” dediler."],["8","Zakkay ayağa kalkıp Efendi’ye şöyle dedi: “İşte, Efendimiz, malımın yarısını yoksullara veriyorum. Birinden haksız yere bir şey aldıysam, dört katını geri veririm.”"],["9","Yeşua ona, “Bugün bu eve kurtuluş geldi. Çünkü o da Avraham’ın oğludur."],["10","Çünkü İnsanoğlu kaybolanı arayıp kurtarmak için geldi” dedi."],["11","Onlar bu şeyleri dinlerken, Yeşua bir benzetmeyle konuşmasını sürdürdü. Çünkü Yeruşalem’e yakın olduklarından onlar Tanrı’nın Krallığı'nın hemen ortaya çıkacağını sanıyorlardı."],["12","Bu nedenle Yeşua şöyle dedi: “Soylu bir adam, krallık alıp dönmek için uzak bir ülkeye gitti."],["13","On hizmetkârını çağırıp onlara birer mina para verdi. ‘Ben gelene kadar işleri yürütün’ dedi."],["14","Ama ülke halkı adamdan nefret ediyordu. Peşinden elçiler gönderip, ‘Biz bu adamın üzerimizde hüküm sürmesini istemiyoruz’ dediler."],["15","“Kralllığı alıp geri döndüğünde, parayı vermiş olduğu bu hizmetkârlarının yanına çağrılmasını buyurdu, parasıyla ne kazandıklarını bilmek istedi."],["16","Birincisi, ‘Efendimiz, senin bir minan on mina daha kazandı’ diyerek önüne geldi.”"],["17","“Ona, ‘Aferin, iyi hizmetkâr! Çok azında sadık bulunduğun için, on kent üzerinde yetkili olacaksın.’”"],["18","“İkincisi, ‘Efendimiz, senin bir minan beş mina daha kazandı’ diyerek efendisinin önüne geldi.”"],["19","“O da ona, ‘Sen de beş kent üzerinde yetkili olacaksın.’"],["20","Diğeri gelip, ‘Efendimiz, işte, mendile sarıp sakladığım minan."],["21","Çünkü senden korktum. Zira sert bir adamsın. Sen koymadığını kaldırır, ekmediğini biçersin.’”"],["22","“Efendisi ona, ‘Ey kötü hizmetkâr, seni kendi ağzınla yargılayacağım! Benim koymadığımı toplayan, ekmediğimi biçen sert bir adam olduğumu biliyordun."],["23","O halde neden paramı bankaya vermedin? Geldiğimde onu faiziyle alırdım.’"],["24","Yanında duranlara, ‘Elindeki minayı ondan alın ve on minası olana verin’ dedi.”"],["25","“Ona, ‘Efendimiz, onun on minası var’ dediler."],["26","‘Size şunu söyleyeyim, kimde varsa, ona daha çok verilecek. Ama kimde yoksa, elindeki bile alınacaktır."],["27","Ama üzerlerinde hüküm sürmemi istemeyen şu düşmanlarımı buraya getirin ve önümde öldürün.’”"],["28","Yeşua bunları söyledikten sonra ilerleyip Yeruşalem’e çıktı."],["29","Yeşua, Beytfaci ile Beytanya’ya yaklaştığında, zeytinlik denilen dağda, iki öğrencisini gönderdi."],["30","Onlara, “Karşı taraftaki köye gidin, oraya girince üzerine henüz hiç kimsenin binmediği, bağlı bir sıpa bulacaksınız. Onu çözüp getirin."],["31","Eğer biri size, ‘Onu neden çözüyorsun?’ diye sorarsa, ‘Efendi’nin ihtiyacı var’ deyin” dedi."],["32","Gönderilenler gittiler ve Yeşua’nın kendilerine söylediği gibi buldular."],["33","Sıpayı çözerken, sahipleri onlara, “Sıpayı neden çözüyorsunuz?” dediler."],["34","Onlar da, “Efendi’nin ona ihtiyacı var” dediler."],["35","Sonra sıpayı alıp Yeşua’ya getirdiler. Kendi giysilerini sıpanın üzerine attılar Yeşua’yı üstüne bindirdiler."],["36","Yeşua giderken, onlar giysilerini yola serdi."],["37","Yeşua Zeytin Dağı’nın alt yamacına yaklaştığında, öğrencilerin tümü, görmüş oldukları büyük işlerden dolayı, sevinip yüksek sesle Tanrı’ya övgüler sunmaya başladılar."],["38","“Efendi’nin adıyla gelen Kral’a övgüler olsun! Gökte esenlik, en yücelerde yücelik olsun!” dediler."],["39","Kalabalıktan bazı Ferisiler Yeşua’ya, “Öğretmen, öğrencilerini azarla!” dediler."],["40","Yeşua onlara, “Size şunu söyleyeyim, eğer bunlar susarsa, taşlar bağıracaktır!” diye karşılık verdi."],["41","Yeşua yaklaşıp kenti gördü ve onun için ağlayıp dedi,"],["42","“Eğer sen, evet sen bugün esenliğine ait olan şeyleri bilseydin! Ama şimdi onlar senin gözlerine saklıdır."],["43","Çünkü senin üzerine günler gelecek ki, düşmanların çevrende siper kurup seni kuşatacaklar, her yandan sıkıştıracaklar."],["44","Seni de çocuklarını de yere çalacaklar. Sende taş üstünde taş bırakmayacaklar. Çünkü kendi ziyaret vaktini bilmedin.”"],["45","Yeşua tapınağa girip oradaki alıp satanları kovmaya başladı."],["46","Onlara şöyle dedi, ‘‘‘Evim dua evidir’ diye yazılmıştır, ama siz onu haydut ini yaptınız!”"],["47","Yeşua her gün tapınakta öğretiyordu. Başkâhinler, yazıcılar ve halkın ileri gelenleri ise O’nu yok etmenin yolunu arıyordu."],["48","Ne yapacaklarını bulamıyorlardı. Çünkü bütün halk O’nun söylemiş olduğu her söze tutulmuştu."]],20:[["1","O günlerden birinde, Yeşua tapınakta halka öğretip Müjde’yi duyururken, kâhinler ve yazıcılar, ihtiyarlarla birlikte O’na geldiler."],["2","O’na, “Söyle bize, bu şeyleri hangi yetkiyle yapıyorsun? Bu yetkiyi sana kim verdi?” diye sordular."],["3","Yeşua onlara şöyle karşılık verdi: “Ben de size bir soru soracağım. Söyleyin bana,"],["4","Yuhanna’nın vaftiz etme yetkisi gökten mi, yoksa insanlardan mıydı?”"],["5","Kendi aralarında şöyle tartıştılar: “‘Gökten’ dersek, ‘Ona neden inanmadınız?’ diyecek."],["6","Ama ‘İnsanlardan’ dersek, bütün halk bizi taşlayacak. Çünkü Yuhanna’nın peygamber olduğuna kanmışlardır.”"],["7","Nereden olduğunu bilmiyoruz diye yanıt verdiler."],["8","Yeşua onlara, “Öyleyse ben de size bu şeyleri hangi yetkiyle yaptığımı söylemeyeceğim” dedi."],["9","Yeşua halka şu benzetmeyi anlatmaya başladı. “Bir adam bir bağ dikti ve onu çiftçilere kiralayıp uzun bir süreliğine başka bir ülkeye gitti."],["10","Mevsiminde bağın ürününden payına düşeni alması için çiftçilere bir hizmetkârını gönderdi. Ama çiftçiler onu dövüp boş gönderdiler."],["11","Adam başka bir hizmetkâr daha gönderdi. Onu da aynı şekilde dövdüler, aşağıladılar ve boş gönderdiler."],["12","Adam bir üçüncüsünü daha gönderdi. Onlar onu da yaralayıp dışarı attılar."],["13","Bağın efendisi, ‘Ne yapayım? Sevgili oğlumu göndereyim. Belki ona saygı gösterirler’ dedi.”"],["14","“Ama çiftçiler onu görünce kendi aralarında, ‘Mirasçı budur. Gelin onu öldürelim de mirası bizim olsun’ dediler."],["15","Sonra onu bağdan dışarı atıp öldürdüler. Öyleyse bağın efendisi şimdi onlara ne yapacak?"],["16","Gelip bu çiftçileri yok edecek ve bağı da başkalarına verecek.” Bunu duyanlar, “Asla, Tanrı korusun!” dediler."],["17","Yeşua onlara baktı ve şöyle dedi: “Öyleyse yazılmış olan bu nedir? ‘Yapıcıların reddettiği taş, köşenin baş taşı oldu.’"],["18","O taşın üzerine düşen herkes parçalanacak. Ancak taş kimin üstüne düşerse onu ezip toz edecek.”"],["19","Yeşua’nın bu benzetmeyi kendilerine karşı söylediğini bilen başkâhinler ve yazıcılar tam o sırada O’nun üzerine ellerini koymak istediler ama halktan korktular."],["20","Yeşua’yı gözlüyorlardı. O’nu kendi sözüyle tuzağa düşürüp valinin yetki ve yargısına teslim edebilmek için kendilerini dürüstmüş gibi gösteren bazı muhbirler gönderdiler."],["21","Bunlar Yeşua’ya, “Öğretmenimiz, senin doğruyu söyleyip öğrettiğini, kimseyi kayırmadan Tanrı yolunu dürüstçe öğrettiğini biliyoruz."],["22","Sezar’a vergi vermemiz Yasa’ya uygun mudur, değil midir?” diye sordular."],["23","Ama onların kurnazlığını anlayan Yeşua, “Beni neden sınıyorsunuz?"],["24","Bana bir dinar gösterin. Üzerinde kimin sureti ve yazısı var?” dedi. “Sezar’ın” diye yanıtladılar."],["25","Bunun üzerine Yeşua, “Öyleyse Sezar’ın şeylerini Sezar’a, Tanrı’nın şeylerini Tanrı’ya verin” dedi."],["26","O’nu halkın önünde kendi sözleriyle tuzağa düşüremediler. Yeşua’nın vermiş olduğu yanıt onları şaşırtmış ve susturmuştu."],["27","Ölümden sonra dirilişi inkâr eden Sadukiler’den bazıları Yeşua’ya geldi."],["28","O’na şunu sordular: “Öğretmenimiz, Moşe bize, ‘bir adamın evli kardeşi çocuksuz ölürse, adam ölenin karısını alıp kardeşine soy yetiştirsin’ diye yazmıştır."],["29","Bu nedenle yedi kardeş vardı. İlki kadını aldı ve çocuksuz öldü."],["30","İkincisi de kadını aldı ve çocuksuz öldü."],["31","Üçüncüsü de onu aldı ve aynı şekilde kardeşlerin yedisi de çocuk bırakmadan öldü."],["32","Daha sonra kadın da öldü."],["33","Dirilişte bu kadın hangisinin karısı olacak? Çünkü yedisi de onu aldı.”"],["34","Yeşua onlara şöyle dedi: “Bu çağın çocukları evlenir ve evlendirilir."],["35","Ama o çağda ve ölülerin dirilişine layık görülenler ne evlenirler, ne de evlendirilirler."],["36","Artık bir daha ölemezler. Çünkü melekler gibidirler ve dirilişin çocukları olarak Tanrı’nın çocuklarıdırlar."],["37","Ama Moşe bile çalı olayında, ‘Avraham’ın Tanrısı, İshak’ın Tanrısı ve Yakov’un Tanrısı’ diye çağırarak ölülerin dirileceğini göstermiştir."],["38","Tanrı ölülerin değil, dirilerin Tanrısı’dır, çünkü hepsi O’na diridirler.”"],["39","Yazıcılardan bazıları, “Öğretmenimiz, güzel konuştun” diye yanıtladı."],["40","Bundan sonra O’na daha fazla soru sormaya cesaret edemediler."],["41","Yeşua onlara şöyle dedi: “Neden Mesih için David’in Oğlu olduğunu söylüyorlar?"],["42","Çünkü David’in kendisi Mezmurlar Kitabı’nda şöyle diyor: ‘Efendi Efendim’e dedi ki, sağımda otur,"],["43","ta ki düşmanlarını ayaklarının altına basamak yapıncaya dek.’”"],["44","“David O’na Efendi diyorsa, O nasıl David’in Oğlu olabilir?”"],["45","Bütün halk dinlerken Yeşua öğrencilerine şöyle dedi:"],["46","“Uzun kaftanlar içinde dolaşmaktan hoşlanan, çarşı meydanlarında selamlanmayı, havralarda en iyi yerleri oturup ziyafetlerde baş yerleri seven yazıcılardan sakının."],["47","Onlar dul kadınların evlerini yutarlar, gösteriş için uzun dualar ederler. Bunların mahkûmiyeti daha büyük olacaktır.”"]],21:[["1","Yeşua başını kaldırdı ve hazineye hediyelerini koyan zenginleri gördü."],["2","Yoksul bir dul kadının da iki küçük bakır para attığını gördü."],["3","Yeşua, “Size gerçeği söyleyeyim, bu yoksul dul kadın herkesten daha çok koydu."],["4","Çünkü bunların hepsi Tanrı için bolluklarından artanı koydular” dedi. “Ama kadın ise yoksulluğundan yaşamak için elinde ne varsa onu koydu.”"],["5","Bazıları tapınağın nasıl güzel taşlarla ve sunularla süslenmiş olduğundan söz ediyordu."],["6","Yeşua, “Gördüğünüz bu şeylere gelince, öyle günler gelecek ki, burada yıkılmadık taş üstünde taş bırakılmayacak.” dedi."],["7","Kendisine, “Öğretmenimiz, bu şeyler ne zaman olacak?” diye sordular. “Bu şeyler olmak üzereyken, işaret ne olacak?”"],["8","Yeşua, “Dikkat edin, saptırılmayasınız!” dedi. “Çünkü birçokları, ‘Ben O’yum ’ ve ‘Zamanı geldi’ diyerek benim adımla gelecekler. Bu nedenle onların peşinden gitmeyin."],["9","Savaş ve kargaşa haberleri duyduğunuzda korkmayın. Çünkü önce bunların olması gerek, ama son hemen gelmeyecek.”"],["10","Sonra onlara, “Ulus ulusa, krallık krallığa karşı ayaklanacak."],["11","Çeşitli yerlerde büyük depremler, kıtlıklar ve salgın hastalıklar olacak. Gökte korkunç şeyler, büyük belirtiler olacak."],["12","Ama bütün bu şeylerden önce, ellerini üzerinize koyup, size zulmedecekler. Sizi havralara teslim edip zindanlara atacaklar. Benim adımdan ötürü sizi kralların ve valilerin önüne çıkaracaklar."],["13","Bu size tanıklık olacaktır."],["14","Bu nedenle, nasıl yanıt vereceğinizi önceden düşünmemeyi yüreğinize koyun."],["15","Çünkü ben size, size karşı çıkanların hiçbirinin karşı koyamayacağı ya da aksini söyleyemeyeceği bir ağız ve bilgelik vereceğim."],["16","Anne babanız, kardeşleriniz, akrabalarınız ve dostlarınız tarafından bile ele verileceksiniz. Bazılarınızın ölümüne sebep olacaklar."],["17","Benim adımdan dolayı herkes sizden nefret edecek."],["18","Başınızdaki saçlardan bir tel bile yok olmayacaktır.”"],["19","“Dayanmakla hayatınızı kazanacaksınız.”"],["20","“Ama Yeruşalem’in ordular tarafından kuşatıldığını gördüğünüzde, bilin ki, onun yıkımı yakındır."],["21","O zaman Yahudiye’de olanlar dağlara kaçsın. Kentin içinde olanlar çıksın. Kırdakiler oraya girmesin."],["22","Çünkü o günler, yazılmış olan her şeyin yerine geleceği öç alma günleridir."],["23","O günlerde gebe olan, çocuk emzirenlerin vay haline! Çünkü ülkede büyük sıkıntı olacak ve bu halka gazap gelecektir."],["24","Kılıçtan geçirilip, bütün uluslara tutsak olarak sürülecekler. Yeruşalem, öteki ulusların zamanları doluncaya dek, öteki uluslar tarafından çiğnenecektir."],["25","Güneşte, ayda ve yıldızlarda belirtiler olacak. Yeryüzündeki uluslar denizin ve dalgaların uğultusundan şaşkına dönüp sıkıntı içinde kalacak."],["26","Dünyanın başına gelecek şeyleri bekleyen insanlar korkudan bayılacak. Çünkü göklerin güçleri sarsılacak."],["27","O zaman İnsanoğlu’nun bulut içinde güç ve büyük görkemle geldiğini görecekler."],["28","Ama bu şeyler olmaya başlayınca, yukarı bakın ve başınızı kaldırın, çünkü kurtuluşunuz yakındır.”"],["29","Yeşua onlara bir benzetme söyledi: “İncir ağacına ve bütün ağaçlara bakın."],["30","Tomurcuklandıklarında, yazın yakın olduğunu kendiliğinizden bilirsiniz."],["31","Böylece, siz de bu şeylerin gerçekleştiğini gördüğünüzde, Tanrı’nın Krallığı'nın yakın olduğunu bilin."],["32","Size doğrusunu söyleyeyim, bu şeylerin tümü yerine gelinceye dek bu kuşak geçmeyecektir."],["33","Gök ve yer geçecek, ama benim sözlerim hiçbir şekilde geçmeyecektir.”"],["34","“Öyleyse dikkat edin! Yoksa yüreğiniz sefahat, sarhoşluk ve bu hayatın kaygılarıyla ağırlaşır ve o gün ansızın üzerinize gelir."],["35","Çünkü o gün yeryüzünde oturan herkesin üzerine bir tuzak gibi gelecektir."],["36","Bu nedenle, gerçekleşecek bütün bu şeylerden kaçabilmek ve İnsanoğlu’nun önünde durabilmek için her an uyanık kalıp dua edin.”"],["37","Yeşua gündüzleri tapınakta öğretiyor, geceleri Zeytinlik denilen dağa çekilip orada geceliyordu."],["38","Bütün halk sabah erkenden O’nu dinlemek için tapınağa geliyordu."]],22:[["1","Pesah denilen Mayasız Ekmek Bayramı yaklaşıyordu."],["2","Başkâhinlerle yazıcılar, Yeşua’yı öldürmenin bir yolunu arıyor ama halktan da korkuyorlardı."],["3","Şeytan, Onikiler’den sayılan İskariot denilen Yahuda’nın içine girdi."],["4","O gidip başkâhinlerle ve tapınak koruyucularının komutanlarıyla Yeşua’yı nasıl onların eline teslim edeceğini konuştu."],["5","Onlar memnun oldular ve kendisine para vermek için anlaştılar."],["6","Bunu kabul eden Yahuda, halkın yokluğunda Yeşua’yı onların eline teslim etmek için fırsat arıyordu."],["7","Pesah kurbanının kesilmesi gereken Mayasız Ekmek Günü geldi."],["8","Yeşua, Petrus’la Yuhanna’yı, “Gidin Pesah'ı yiyebilmemiz için hazırlık yapın” diyerek gönderdi."],["9","O'na, “Nerede hazırlamamızı istersin?” dediler."],["10","Onlara şöyle dedi: “Kente girdiğinizde, testiyle su taşıyan bir adam karşınıza çıkacak. Adamın gireceği eve onun ardından girin."],["11","Evin efendisine şöyle deyin: ‘Öğretmen size, öğrencilerimle birlikte Pesah yemeğini yiyebileceğim misafir odası nerede? diyor.’"],["12","Size üst katta, döşenmiş büyük bir oda gösterecek. Hazırlığı orada yapın.”"],["13","Onlar gittiler, Yeşua’nın kendilerine söylemiş olduğu gibi buldular ve Pesah'ı hazırladılar."],["14","Saat gelince Yeşua on iki elçisiyle birlikte oturdu."],["15","Yeşua onlara, “Ben acı çekmeden önce bu Pesah yemeğini sizinle birlikte yemeyi çok istedim” dedi."],["16","“Size şunu söyleyeyim, Tanrı’nın Krallığı'nda tamamlanıncaya dek, ondan bir daha hiçbir şekilde yemeyeceğim.”"],["17","Sonra bir kâse aldı ve şükrettikten sonra, “Bunu alın ve aranızda paylaşın” dedi."],["18","“Size şunu söyleyeyim, Tanrı’nın Krallığı gelene dek asmanın ürününden bir daha hiç içmeyeceğim.”"],["19","Sonra eline ekmek aldı. Şükrettikten sonra böldü ve onlara verip, “Bu sizin için verilen benim bedenimdir. Bunu beni anmak için yapın” dedi."],["20","Aynı şekilde, akşam yemeğinden sonra kâseyi alıp şöyle dedi: “Bu kâse sizin için dökülen kanımla gerçekleşen yeni antlaşmadır."],["21","Ama işte, bana ihanet edenin eli benimle birlikte sofradadır."],["22","Gerçi İnsanoğlu, belirlendiği gibi gidiyor. Ama vay o adamın haline ki, kendisi aracılığıyla O'na ihanet ediliyor!”"],["23","Kendilerinden bu şeyi kim yapacak diye aralarında sorgulamaya başladılar."],["24","Aralarında en büyük hangisinin olduğu konusunda da bir anlaşmazlık çıktı."],["25","Yeşua onlara şöyle dedi: “Ulusların kralları onların üzerinde efendilik ederler, üzerlerindeki hüküm sahiplerine iyiliksever denilir."],["26","Ama sizin için böyle olmasın. Aranızda büyük olan, en küçük gibi olsun. Yöneten de hizmet eden gibi olsun."],["27","Kim daha büyük, sofrada oturan mı, hizmet eden mi? Sofrada oturan değil mi? Ama ben sizin aranızda hizmet eden biri gibiyim."],["28","Sizler denendiğim zamanlarda benimle birlikte dayanmış olanlarsınız."],["29","Babam’ın bana verdiği gibi ben de size bir krallık veriyorum."],["30","Öyle ki, krallığımda soframda yiyip içesiniz. Tahtlarda oturup İsrael’in on iki oymağını yargılayasınız.”"],["31","Efendi şöyle dedi: “Simon, Simon, işte, Şeytan buğday gibi kalburdan geçireyim diye sizin hepinizi istedi."],["32","Ben imanın tükenmesin diye senin için dua ettim. Sen de geri döndüğünde kardeşlerini pekiştir.”"],["33","Simon Yeşua’ya, “Efendimiz, seninle birlikte zindana da, ölüme de hazırım” dedi."],["34","Yeşua, “Sana şunu söyleyeyim, Petrus, beni tanıdığını üç kez inkâr etmeden, bugün horoz kesinlikle ötmeyecek” dedi."],["35","Onlara, “Ben sizi kesesiz, torbasız ve çarıksız gönderdiğimde, bir eksiğiniz var mıydı?” diye sordu. “Hiçbir şey” dediler."],["36","Sonra onlara, “Ama şimdi para kesesi olan onu alsın, torbası olan da alsın. Olmayan giysisini satıp bir kılıç alsın."],["37","Çünkü size şunu söyleyeyim, yazılmış olan şu sözün bende yerine gelmesi gerekiyor: ‘O, suçlularla bir sayıldı.’ Çünkü benim hakkında olan yerine geliyor.” dedi."],["38","“Efendimiz, işte, burada iki kılıç” dediler. O da onlara, “Yeter!” dedi."],["39","Yeşua çıktı, her zaman olduğu gibi Zeytin Dağı’na gitti. Öğrencileri de O'nu izledi."],["40","Oraya varınca onlara, “Dua edin ki, ayartı içine girmeyesiniz” dedi."],["41","Onlardan bir taş atımı kadar uzaklaştı. Orada diz çöküp dua etti."],["42","“Baba, eğer istersen bu kâseyi benden uzaklaştır. Yine de benim isteğim değil, seninki olsun” dedi."],["43","Gökten bir melek Yeşua’ya görünerek O’nu güçlendirdi."],["44","Derin bir acı içinde olduğundan daha hararetle dua etti. Teri yere düşen iri kan damlaları gibi toprağa düşüyordu."],["45","Yeşua duadan kalkıp öğrencilerin yanına geldi. Onları kederden uyumuş buldu."],["46","Onlara, “Niçin uyuyorsunuz? Kalkıp dua edin ki, ayartı içine girmeyesiniz” dedi."],["47","O daha konuşurken bir kalabalık belirdi. Onikiler’den biri, Yahuda onlara öncülük ediyordu. Yahuda öpmek için Yeşua’ya yaklaştı."],["48","Ancak Yeşua ona, “Yahuda, İnsanoğlu’nu bir öpücükle mi ihanet ediyorsun?” dedi."],["49","Yeşua’nın yanındakiler olacakları görünce, “Efendimiz, kılıçla vuralım mı?” dediler."],["50","Onlardan biri başkâhinin hizmetkârına vurduğu gibi sağ kulağını kesti."],["51","Ama Yeşua, “Bırakın en azından şunu yapayım” dedi ve hizmetkârın kulağına dokunup onu iyileştirdi."],["52","Yeşua kendisini yakalamaya gelen başkâhinlere, tapınak görevlileri ve ihtiyarlara şöyle dedi: “Bir hayduta karşıymış gibi kılıç ve sopalarla çıktınız?"],["53","Her gün tapınakta sizinleyken, bana karşı elinizi uzatmadınız. Ama bu, sizin saatinizdir ve karanlığın gücüdür.”"],["54","Yeşua’yı yakalayıp götürdüler, O'nu başkâhinin evine getirdiler. Ama Petrus uzaktan takip ediyordu."],["55","Avlunun ortasında ateş yakıp birlikte oturduklarında, Petrus da onların arasında oturdu."],["56","Bir hizmetçi kız ateşin ışığında oturan Petrus’u gördü. Onu dikkatlice bakıp, “Bu adam da O’nunla birlikteydi” dedi"],["57","Ama Petrus, “Kadın, O’nu tanımıyorum” diyerek Yeşua’yı inkâr etti."],["58","Kısa bir süre sonra onu gören başka biri, “Sen de onlardan birisin!” dedi. Ama Petrus, “Değilim, be adam!” dedi."],["59","Yaklaşık bir saat geçtikten sonra, bir başkası emin bir şekilde, “Gerçekten bu adam da O’nunla birlikteydi. Çünkü o bir Galileli!” dedi."],["60","Ama Petrus, “Be adam, neden söz ettiğini bilmiyorum!” dedi. Petrus daha konuşurken hemen horoz öttü."],["61","Efendi dönüp Petrus’a baktı. O zaman Petrus Efendi’nin kendisine, “Horoz ötmeden beni üç kez inkâr edeceksin” dediği sözü hatırladı."],["62","Dışarı çıkıp acı acı ağladı."],["63","Yeşua’yı göz altında tutan adamlar O’nunla alay edip O’nu dövdüler."],["64","Gözlerini bağlayıp yüzüne vurdular ve O'na, “Peygamberlik et! Sana vuran kimdir?” diye sordular."],["65","O’nu aşağılayıp, O'na karşı başka çok şeyler söylediler."],["66","Gündüz olunca, başkâhinler, yazıcılar ve halkın ihtiyarları toplandılar. Yeşua’yı Kurul’un önüne götürüp,"],["67","“Eğer sen Mesih isen, söyle bize” dediler. Ama Yeşua onlara, “Eğer size söylersem inanmayacaksınız."],["68","Eğer size sorsam, kesin olarak yanıtlamayacak, beni bırakmayacaksınız."],["69","Bundan böyle İnsanoğlu, Tanrı’nın gücünün sağında oturacaktır” dedi."],["70","Hepsi, “Öyleyse sen Tanrı’nın Oğlu musun?” dediler. Onlara, “Söylediğiniz gibi, Ben’im” dedi."],["71","“Artık neden daha fazla tanığa ihtiyacımız olsun ki! Çünkü biz kendimiz O'nun kendi ağzından duyduk!” dediler."]],23:[["1","Onların bütün topluluğu kalkıp Yeşua’yı Pilatus’un önüne götürdüler."],["2","Şöyle deyip O’nu suçlamaya başladılar, “Bu adamın ulusumuzu saptırdığını, Sezar’a vergi ödenmesini yasakladığını, kendisinin de Mesih, bir kral olduğunu söylediğini keşfettik.”"],["3","Pilatus O’na, “Sen Yahudiler’in Kralı mısın?” diye sordu. “Söylediğin gibidir” yanıtını verdi."],["4","Pilatus başkâhinlere ve kalabalığa, “Bu adamı suçlamak için hiçbir neden bulmuyorum” dedi."],["5","Ama onlar ısrar edip, “Halkı kışkırtıyor. Galile'den başlayıp hatta buraya kadar bütün Yahudiye'de öğretiyor” dediler."],["6","Pilatus, Galile dendiğini duyunca, “Bu adam Galileli mi?” diye sordu."],["7","Yeşua’nın Hirodes’in yetki alanındaki bölgeden olduğunu öğrenince, O’nu o günlerde Yeruşalem’de bulunan Hirodes’e gönderdi."],["8","Hirodes Yeşua’yı görünce çok sevindi. Çünkü uzun zamandır O’nu görmek istiyordu, çünkü O’nun hakkında çok şey duymuştu. O'nun tarafından yapılacak bir mucizeyi görmeyi umuyordu."],["9","Yeşua’yı çok sözlerle sorguya çekti. Ama O hiç yanıt vermedi."],["10","Başkâhinlerle yazıcılar ayağa kalkıp Yeşua’yı sert sözlerle suçladı."],["11","Hirodes de askerleriyle birlikte O’nu aşağılayıp O'nunla alay etti. Hirodes O’na gösterişli bir giysi giydirip Pilatus’a geri gönderdi."],["12","Önceden birbirlerine düşman olan Hirodes ve Pilatus o günde birbirleriyle dost oldular."],["13","Pilatus başkâhinleri, yöneticileri ve halkı bir araya topladı."],["14","Onlara, “Bu adam halkı yoldan saptırıyor diye bana getirdiniz. İşte, ben de O’nu sizin önünüzde sorguya çektim ve bu adama karşı O'nu suçladığınız şeylerle ilgili hiçbir neden bulmadım."],["15","Hirodes de bir suç bulamamış, çünkü O’nu bize geri gönderdi. O'nun tarafından ölüm cezasını gerektirecek hiçbir şey yapılmamıştır."],["16","Bu nedenle O’nu döveceğim ve salıvereceğim” dedi."],["17","Pilatus’un bayramda onlara bir kişiyi salıvermesi gerekiyordu."],["18","Ama onlar hep bir ağızdan, “Bu adamı ortadan kaldır! Bize Barabba’yı salıver!” diye bağırdılar."],["19","Barabba kentte çıkan bir isyandan ve adam öldürmekten hapse atılmıştı."],["20","Sonra Yeşua’yı salıvermek isteyen Pilatus onlara yeniden seslendi."],["21","Ama onlar ise, “Çarmıha ger! Onu çarmıha ger!” diye bağırdılar."],["22","Üçüncü kez onlara, “Neden? Bu adam ne kötülük yaptı? Ben O’nda ölüm cezasını gerektiren bir suç bulmadım. Bu nedenle O’nu döveceğim serbest bırakacağım” dedi."],["23","Ama onlar çarmıha gerilmesini isteyerek yüksek sesle ısrar ettiler. Halkın ve başkâhinlerin sesleri üstün geldi."],["24","Pilatus, istediklerinin yapılmasına karar verdi."],["25","İsyan ve adam öldürmekten hapse atılan, onların istediği kişiyi salıverdi. Ama Yeşua’yı onların isteğine bıraktı."],["26","Yeşua’yı götürürken, Kireneli Simon adında bir adam kırdan geliyordu. Onu Yeşua’nın çarmıhını taşıması için yakaladılar. Yeşua'nın ardından çarmıhı ona yüklediler."],["27","Halktan büyük bir kalabalık Yeşua’nın ardından gidiyordu. Yas tutan ve O’nun için ağıt yakan kadınlar da bunların arasındaydı."],["28","Yeşua onlara dönerek, “Ey Yeruşalem kızları, benim için ağlamayın, kendiniz ve çocuklarınız için ağlayın."],["29","Çünkü işte, günler gelecek ki, ‘Kısır kadınlara, hiç doğurmamış rahimlere, emzirmemiş memelere ne mutlu!’ diyecekler."],["30","O zaman dağlara, ‘Üzerimize düşün’ ve tepelere, ‘Bizi örtün’ demeye başlayacaklar."],["31","Eğer bu şeyleri yaş ağaca yaparlarsa, kuruya neler yapmazlar?” dedi."],["32","Yeşua’yla birlikte idam edilmek üzere iki suçlu daha götürülüyordu."],["33","“Kafatası” denilen yere geldiklerinde Yeşua’yı, biri sağında diğeri solunda olmak üzere iki suçluyla birlikte çarmıha gerdiler."],["34","Yeşua, “Baba, onları bağışla, çünkü ne yaptıklarını bilmiyorlar” dedi. Kura çekip O’nun giysilerini aralarında paylaştılar."],["35","Halk durmuş izliyordu. Yanlarındaki yöneticiler de O’nunla alay edip, “Başkalarını kurtardı. Eğer gerçekten Tanrı’nın Mesih’i, O'nun seçilmişi ise kendini kurtarsın!” diyorlardı."],["36","Askerler de O’nunla alay ettiler, yanına gelip sirke verdiler."],["37","“Eğer Yahudiler’in Kralı isen, kendini kurtar!” dediler."],["38","Başının üzerinde Grekçe, Latince ve İbranice harflerle yazılmış şu yafta vardı: “YAHUDİLER’İN KRALI BUDUR.”"],["39","Çarmıha asılan suçlulardan biri, “Eğer Mesih isen, kendini de bizi de kurtar!” diyerek O’na hakaret etti."],["40","Ama diğer suçlu karşılık verip onu azarladı. “Sen Tanrı'dan korkmuyor musun? Sen de aynı cezayı çekiyorsun."],["41","Biz gerçekten haklı olarak, yaptıklarımızın karşılığını alıyoruz. Ama bu adam hiçbir kötülük yapmadı” dedi."],["42","Sonra Yeşua’ya, “Efendimiz, krallığına girdiğinde beni hatırla” dedi."],["43","Yeşua ona, “Sana doğrusunu söyleyeyim, bugün sen benimle birlikte cennette olacaksın” dedi."],["44","Altıncı vakit sıralarıydı, dokuzuncu vakte kadar bütün ülkenin üzerine karanlık çöktü."],["45","Güneş karardı, tapınağın perdesi ortadan ikiye yırtıldı."],["46","Yeşua yüksek sesle, “Baba, ruhumu senin ellerine teslim ediyorum!” diye bağırdı. Bunu söyledikten sonra son nefesini verdi."],["47","Olanı gören yüzbaşı Tanrı’yı yücelterek, “Hiç kuşkusuz, bu adam doğru biriydi” dedi."],["48","Bunu görmek için toplanan kalabalığın tümü olup bitenleri görünce göğüslerini döverek eve döndüler."],["49","Yeşua’nın bütün tanıdıkları ve O’nunla birlikte Galile’den gelmiş olan kadınlar uzakta durmuş, bu şeyleri izliyorlardı."],["50","İşte, Yüksek Kurul üyesi Yosef adında iyi ve doğru bir adam vardı."],["51","Yosef Kurul’un kararını ve işini kabul etmemişti. Tanrı’nın Krallığı'nı bekleyen bir Yahudi olan Yosef Aramatya Kenti’ndendi."],["52","Bu adam Pilatus’a gidip Yeşua’nın cesedini istedi."],["53","Cesedi indirip keten bir beze sardı ve O’nu daha önce kimsenin yatırılmadığı, kayaya oyulmuş bir mezara yatırdı."],["54","Hazırlık Günü’ydü ve Şabat yaklaşıyordu."],["55","Galile’den Yeşua’yla birlikte gelen kadınlar peşinden gittiler ve mezarı ve cesedinin nereye yatırıldığını gördüler."],["56","Sonra geri dönüp baharat ve güzel kokulu yağlar hazırladılar. Şabat'da buyruğa göre dinlendiler."]],24:[["1","Onlar ve bazıları ise haftanın ilk gününde, şafak vaktinde, hazırladıkları baharatları yanlarına alıp mezara geldiler."],["2","Taşı mezarın girişinden yuvarlanmış buldular."],["3","İçeri girdiklerinde Efendi Yeşua’nın cesedini bulamadılar."],["4","Onlar bunun şaşkınlığı içindeyken, işte, parlak giysilerle iki adam yanlarında durdu."],["5","Kadınlar korkup yüzlerini yere eğdiler. Adamlar ise, “Diri olanı neden ölüler arasında arıyorsunuz?"],["6","O burada değil, dirildi. Daha Galile’deyken size neler söylediğini hatırlayın."],["7","İnsanoğlu’nun günahkâr insanların eline teslim edilmesi, çarmıha gerilmesi ve üçüncü gün dirilmesi gerektiğini bildirmişti” dedi."],["8","Kadınlar Yeşua’nın sözlerini hatırladılar."],["9","Mezardan geri dönüp bütün bu şeyleri Onbirler’e ve diğerlerine anlattılar."],["10","Bunları elçilere bildirenler, Magdalalı Mariyam, Yohanna, Yakov’un annesi Mariyam ve onlarla birlikte olan diğer kadınlardı."],["11","Bu sözler elçilere saçma geldi ve onlara inanmadılar."],["12","Ama Petrus kalkıp mezara koştu. Eğilip içeri baktığında orada duran keten bezlerin yalnız durduğunu gördü, olan şeye şaşarak evine gitti."],["13","O gün onlardan ikisi, Yeruşalem’den altmış stadia uzaklıkta bulunan Emmaus adlı bir köye gidiyorlardı."],["14","Olan bütün bu şeyleri birbirleriyle konuşuyorlardı."],["15","Birlikte konuşup sorgularken, Yeşua’nın kendisi yaklaştı ve onlarla birlikte gitti."],["16","Ancak onların gözleri O’nu tanımaktan alıkoyulmuştu."],["17","Yeşua onlara, “Yolda yürürken neden söz ediyordunuz ve neden üzgünsünüz?” dedi."],["18","İçlerinden Kleopas adında olan O’na, “Bu günlerde Yeruşalem’de olup da orada olan şeyleri bilmeyen tek yabancı sen misin?” diye yanıtladı."],["19","Onlara, “Hangi şeyler?” dedi. O’na, “Nazaretli Yeşua’yla ilgili şeyler” dediler. “O adam, Tanrı’nın ve bütün halkın önünde hem işte hem de sözde güçlü bir peygamberdi."],["20","Başkâhinlerle yöneticilerimiz O’nun ölüme mahkûm edilmesi ve çarmıha gerilmesi için O'nu nasıl da teslim ettiler."],["21","Ama biz İsrael’i kurtaracak kişinin O olacağını ummuştuk. Evet, tüm bunlarla birlikte üç gün sonra,"],["22","aramızdan bazı kadınlar bizi şaşkına çevirdiler. Sabah erkenden mezara varmışlar."],["23","Cesedini bulamayınca, O’nun yaşadığını bildiren meleklerle ilgili bir de görüm gördüklerini söylemek için geldiler."],["24","Bazılarımız mezara gitti ve tıpkı kadınların söylediği gibi mezarı buldular. Ama O’nu görmemişler.”"],["25","Yeşua onlara, “Sizi akılsızlar, peygamberlerin bütün söylediklerine yürekleri geç inananlar!"],["26","Mesih’in bu şeyleri çekmesi ve kendi yüceliğine girmesi gerekmiyor muydu?” dedi."],["27","Moşe ve bütün peygamberlerden başlayarak, Kutsal Yazılar’ın hepsinde kendisiyle ilgili şeyleri onlara açıkladı."],["28","Gidecekleri köye yaklaştıklarında Yeşua daha ileri gidecekmiş gibi davrandı."],["29","Ama onlar, “Bizimle kal, çünkü neredeyse akşam oluyor, gün batmak üzere” diyerek O’nu zorladılar. Yeşua onlarla kalmak için içeri girdi."],["30","Onlarla birlikte sofrada otururken, Yeşua ekmeği alıp şükretti. Ekmeği kırıp onlara verdi."],["31","Onların gözleri açıldı ve O’nu tanıdılar. O zaman Yeşua gözlerinin önünden kayboldu."],["32","Birbirlerine, “Yol boyunca bizimle konuşurken ve Kutsal Yazılar’ı bize açarken yüreklerimiz yanmıyor muydu?” dediler."],["33","Tam o saatte kalkıp Yeruşalem’e döndüler. Onbirler’i ve onlarla birlikte olanları toplanmış buldular."],["34","Bunlar, “Efendi gerçekten dirildi ve Simon’a göründü!” diyorlardı."],["35","Onlar da yolda olanları, ekmeği kırdığı zaman Yeşua’yı nasıl tanıdıklarını anlattılar."],["36","Onlar bu şeyleri konuşurken, Yeşua’nın kendisi aralarında durup onlara, “Size esenlik olsun” dedi."],["37","Ama onlar dehşete kapıldılar, bir hayalet gördüklerini sanarak korkuyla doldular."],["38","Onlara, “Neden sıkıntı duyuyorsunuz? Yüreğinizde neden kuşkular yükseliyor?"],["39","Ellerime ve ayaklarıma bakın, gerçekten benim. Bana dokunun ve görün. Çünkü hayaletin eti ve kemiği yoktur, gördüğünüz gibi benim var” dedi."],["40","Bunu söyledikten sonra onlara ellerini ve ayaklarını gösterdi."],["41","Öğrenciler sevinçten inanmayıp hâlâ şaşkınlık içindeyken onlara, “Burada yiyecek bir şeyiniz var mı?” diye sordu."],["42","O’na bir parça kızarmış balık ve biraz bal peteği verdiler."],["43","Onları alıp önlerinde yedi."],["44","Yeşua onlara, “Daha sizinle birlikteyken, Moşe’nin Yasası’nda, peygamberlerin yazılarında ve Mezmurlar’da benimle ilgili yazılmış olan her şeyin yerine gelmesi gerektiğini söylemiş olduğum sözler bunlardır” dedi."],["45","Sonra Kutsal Yazılar’ı anlayabilsinler diye zihinlerini açtı."],["46","Onlara şöyle dedi: “Şöyle yazılmıştır: Mesih’in acı çekmesi ve üçüncü gün ölümden dirilmesi gerekir."],["47","Böylece tövbe ve günahların bağışlanması Yeruşalem'den başlayarak bütün uluslara O'nun adında duyurulacaktır."],["48","Siz bu şeylerin tanıklarısınız."],["49","İşte, ben de Babam’ın vaadini size göndereceğim. Ama yücelerden güçle giyinene dek Yeruşalem Kenti'nde bekleyin.”"],["50","Yeşua onları Beytanya’ya kadar götürdü. Ellerini kaldırıp onları kutsadı."],["51","Onları kutsarken onlardan çekildi, göğe alındı."],["52","O’na tapındılar ve büyük bir sevinçle Yeruşalem’e döndüler."],["53","Sürekli tapınakta Tanrı’yı övüyor, yüceltiyorlardı. Amin."]]};export{a as default};
